(window.GIM_TS=window.GIM_TS||{})["Bava Batra.14"]={"from":336,"a":[["\u0003רבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003אין אותיות נקנות במסירה,\u0004 ולכן לא נקנה לו השדה במסירת השטר, וממילא החזקת השטר בידו אינה הוכחה. והוא צריך איפוא להסתמך דווקא על חזקתו. \u0003ורבי סבר\u0004 \u0005[סבור]:\u0006 \u0003אותיות נקנות במסירה,\u0004 ואינו צריך לחזקה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אם כן, פלוגתא לדמר\u0004 \u0005[\u0006הרי זו \u0005מחלוקת על\u0006 דברי \u0005אדוני]\u0006 רבה (רבו של אביי) שפירש את הברייתא שדנו בה בעמוד הקודם, כך שרבן שמעון בן גמליאל סבור שאותיות נקנות במסירה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב דימי: \u0003ותפלוג\u0004 \u0005[ותהיה\u0006 זו \u0005מחלוקת]!\u0006 שאינו חייב להסכים לדברי רבה, ומה בכך?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי, \u0003הכי קאמינא\u0004 \u0005[כך אני אומר]\u0006 \u0003לך:\u0004 \u0003מתניתא לא מיתרצא\u0004 \u0005[הברייתא\u0006 הראשונה \u0005אינה מתיישבת]\u0006 \u0003אלא כדמתרצא מר\u0004 \u0005[כפי שמתרץ\u0006 אותה \u0005אדוני,\u0006 רבה\u0005],\u0006 \u0003ואם כן קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבן שמעון בן גמליאל\u0004 על דברי \u0003רבן שמעון בן גמליאל!\u0004","\u0003אלא אמר אביי:\u0004 גם לדעת רבן שמעון בן גמליאל אותיות נקנות במסירה, ויש לפרש את המחלוקת בשטר וחזקה באופן אחר, \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שנמצא אחד מהן\u0004 מעדי אותו השטר שבידי המחזיק בקרקע, \u0003קרוב או פסול,\u0004","\u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003ר' מאיר ור' אלעזר קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003רבי סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' אלעזר,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים]\u0006 גומרים את הקנין, וכיון שנמסר השטר בעדים (והעדים מעידים על כך), אין חוששים לסמוך עליו,","\u0003ורבן שמעון בן גמליאל סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר,\u0004 ש\u0003אמר: עדי חתימה כרתי\u0004 \u0005[כורתים],\u0006 והואיל והעדות פסולה — השטר פסול, ולא ניתן להסתמך אלא על החזקה בקרקע.","ומקשים: וכי נחלקו ר' מאיר ור' אלעזר במקרה זה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אבא: מודה היה\u0004 גם \u0003ר' אלעזר ב\u0004שטר ה\u0003מזוייף מתוכו,\u0004 כגון שהיה בו עד פסול, \u0003שהוא פסול,\u0004 גם אם נמסר בעדים כשרים!","\u0003אלא אמר ר' אבינא: הכל מודים, שאם כתוב בו: \"הוזקקנו לעדותן של עדים, ונמצאת עדותן מזוייפת\"\u0004 — \u0003שהוא פסול, כ\u0004דברי \u0003ר' אבא,\u0004 שמודה ר' אלעזר במזוייף מתוכו. \u0003לא נחלקו\u0004 רבן שמעון בן גמליאל ורבי, \u0003אלא ב\u0004מקרה שבידי המחזיק היה \u0003שטר שאין עליו עדים כלל,\u0004 ש\u0003רבי סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' אלעזר,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים]\u0006 ואין צורך בעדים החתומים על השטר, ונגמר הקנין במסירת השטר בפני עדים. \u0003ורבן שמעון בן גמליאל סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' מאיר,\u0004 ש\u0003אמר: עדי חתימה כרתי\u0004 \u0005[כורתים]\u0006 ולפיהם קובעים את הדבר. ואם אין עדים בשטר — הריהו פסול, ובוודאי לא קנה בו את השדה, ואם כן יש צורך להסתמך על החזקה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 לא בזה נחלקו, אלא במקרה בו המערער על השדה טוען כי לא היתה כלל מכירה, והשטר שביד המחזיק אבד לו, או שלא נכתב לשם קנין. ו\u0003ב\u0004שאלה האם כשאדם \u0003מודה בשטר ש\u0004הוא \u0003כתבו\u0004 האם \u0003צריך\u0004 מחזיק השטר \u0003לקיימו קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 ש","\u0003רבי סבר\u0004 \u0005[סבור]:\u0006 \u0003מודה בשטר שכתבו\u0004 — \u0003אין צריך\u0004 המחזיק בו \u0003לקיימו,\u0004 וכאן אם מוכר השדה מודה שכתב את השטר — שוב אין צורך בחזקה כהוכחה לבעלות בקרקע. \u0003ורבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003צריך לקיימו,\u0004 ואם אינו יכול לקיימו — עליו להסתמך על החזקה.","ומקשים: \u0003והא איפכא שמעינן להו\u0004 \u0005[והרי היפך\u0006 הדברים הללו \u0005שמענו אותם\u0006 אומרים\u0005]\u0006 במקום אחר! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שנים אדוקין\u0004 (אוחזים) \u0003בשטר\u0004 חוב, \u0003מלוה אומר \"\u0004השטר הזה \u0003שלי הוא ונפל ממני\u0004 לפני שנפרע \u0003ו\u0004אתה \u0003מצאתו\", ולוה אומר\u0004 \"אכן, \u0003שלך הוא, ו\u0004אולם \u0003פרעתיו לך\u0004 ואתה נתתו לי\" — במקרה זה \u0003יתקיים השטר בחותמיו,\u0004 יבדקו אם יש מי שמכיר את חתימות העדים שבו, ואז יגבה בו המלוה. אלו \u0003דברי רבי, רבן שמעון בן גמליאל אומר: יחלוקו;\u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה, ולית ליה\u0004 \u0005[ו\u0006כי \u0005אין לו]\u0006 \u0003לרבי,\u0004 אינו סבור כמו \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שנים אוחזין בטלית, זה אומר \"אני מצאתיה\" וזה אומר \"אני מצאתיה\"\u0004 — \u0003זה ישבע שאין לו בה פחות מחציה, וזה ישבע שאין לו בה פחות מחציה, ויחלוקו?\u0004 ואם כן, מדוע אינו אומר שגם בשנים האוחזים בשטר יחלוקו?","\u0003ואמר רבא אמר רב נחמן: ב\u0004שטר \u0003מקויים\u0004 — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003יחלוקו,\u0004 שהרי לא ברור ממי נפל השטר. \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 הרי זה \u0003ב\u0004שטר \u0003שאינו מקויים,\u0004 ובאופן זה, \u0003רבי סבר\u0004 \u0005[סבור]:\u0006 \u0003מודה בשטר שכתבו\u0004 — \u0003צריך לקיימו, ואי\u0004 \u0005[ואם]\u0006 \u0003מקיים ליה\u0004 \u0005[אותו,\u0006 את השטר\u0005]\u0006 \u0003גבי פלגא\u0004 \u0005[גובה חצי]\u0006 כדין אותה משנה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003חספא בעלמא\u0004 \u0005[\u0006כ\u0005חרס בלבד]\u0006 \u0003הוא\u0004 ואין לו תוקף כלל.","\u0003ורבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]:\u0006 \u0003מודה בשטר שכתבו אין צריך לקיימו, ו\u0004לכן בכל מקרה \u0003יחלוקו!\u0004","ואומרים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות בברייתא האחרונה, ואמור שרבי הוא האומר יחלוקו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם לא תיפוך\u0004 \u0005[אל תהפוך]\u0006 ותשאיר את השיטות במקומן, \u0003אלא הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה האם צריך \u0003לברר קמיפלגי\u0004 \u0005[הם חולקים],\u0006 כלומר, כשאדם טוען מספר טענות, ואינו צריך את כולן, האם צריך ללכת ולברר כל אחת מטענותיו או לא. שלדעת רבי, שאמר שנידון בשטר, כיון שטען המחזיק שיש בידו שטר — עליו להביא גם את השטר לפנינו, למרות שיש בידו חזקה. ואילו לדעת רבן שמעון גמליאל, שאמר שנידון בחזקה — אנו מתעלמים מטענה זו של השטר, ואומרים שכיון שאפשר לדון על פי החזקה די בכך.","ופירוש זה הוא \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב יצחק בר יוסף הוה מסיק ביה זוזי\u0004 \u0005[היה נושה בו כספים]\u0006 \u0003בר' אבא,\u0004 שהלווהו בפני עדים. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יצחק נפחא\u0004 \u0005[הנפח]\u0006 לתבוע את הכסף מר' אבא, \u0003אמר\u0004 ר' אבא: \u0003פרעתיך\u0004 (פרעתי לך) את החוב \u0003בפני פלוני ופלוני. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יצחק:\u0004 אם כן, \u0003יבואו פלוני ופלוני\u0004 העדים \u0003ויעידו. אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא: \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003לא אתו\u0004 \u0005[יבואו]\u0006 העדים האם \u0003לא מהימנינא\u0004 \u0005[אין אני נאמן]?\u0006 \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק לנו]:\u0006 \u0003המלוה את חבירו בעדים\u0004 — \u0003אינו צריך לפרעו בעדים!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא בההיא כשמעתא דמר סבירא לי\u0004 \u0005[אני\u0006 בענין \u0005זה כהלכתו של אדוני,\u0006 \u0005סבור אני],\u0006 ש\u0003אמר ר' אבא אמר רב אדא בר אהבה אמר רב: האומר לחבירו \"פרעתיך בפני פלוני ופלוני\"\u0004 — \u0003צריך שיבואו פלוני ופלוני ויעידו. אמר ליה\u0004 \u0005[לו],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב גידל אמר רב: הלכה כדברי רבן שמעון בן גמליאל\u0004 שאין צריך לברר כל הטענות. \u0003ואף רבי\u0004 החולק ואומר שצריך להביא גם את הראיה בשטר, \u0003לא\u0004"],["\u0003אמר אלא\u0004 שצריך לכתחילה \u0003לברר\u0004 ולקיים את שטרו. אבל אם לא ימצא עדים לקיימו — עדיין יש לו חזקה. ואף כאן, אם לא יבואו העדים — אין הדבר מבטל את טענתי! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא נמי\u0004 \u0005[אני גם כן]\u0006 \u0003לברר קאמינא\u0004 \u0005[אומר אני],\u0006 שעליך לכתחילה להביא את העדים שהזכרת את שמם.","\u0003מי שפרע מקצת חובו\u0004 מה יעשה כדי שלא יצטרך לפרוע את כולו שוב, כשיחזור המלוה ויציג בפניו את שטר החוב? \u0003ר' יהודה אומר: יחליף,\u0004 כלומר, יקרע המלוה את השטר ויכתוב במקומו שטר אחר על הסכום שנותר, \u0003ר' יוסי אומר: יכתוב\u0004 המלוה ללווה \u0003שובר\u0004 (קבלה) על הסכום ששולם לו, והשטר יישאר בידו. \u0003אמר ר' יהודה:\u0004 אם כן \u0003נמצא זה\u0004 הלווה \u0003צריך להיות שומר שוברו מן העכברים,\u0004 שאם יאכלוהו עכברים או יאבד באופן אחר — יצטרך לשלם את מלוא הסכום שבשטר, אף ששילם כבר חלק ממנו! \u0003אמר לו ר' יוסי: כך יפה\u0004 (ראוי) \u0003לו,\u0004 שהוא משועבד למלוה, \u0003ולא ירע כחו של זה\u0004 המלוה.","על האמור במשנתנו \u0003אמר רב הונא אמר רב: אין הלכה לא כר' יהודה ולא כר' יוסי, אלא\u0004 כך עושים במקרה שנפרע מקצת החוב: \u0003בית דין מקרעין\u0004 את \u0003השטר\u0004 הראשון \u0003וכותבין לו\u0004 למלוה \u0003שטר\u0004 חוב \u0003אחר\u0004 בסכום הנותר, ובשטר החדש ייכתב זמן החוב \u0003מזמן\u0004 של השטר ה\u0003ראשון,\u0004 כך שאין אף אחד מהם מפסיד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרב הונא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב ירמיה בר אבא לרב הונא: אי שמיעא ליה\u0004 \u0005[אם היתה נשמעת,\u0006 נודעת \u0005לו]\u0006 \u0003לרב הא\u0004 \u0005[זו]\u0006 ה\u0003ברייתא דתניא\u0004 \u0005[ששנויה]\u0006 בשיטתו של ר' יהודה: \u0003עדים מקרעין את השטר וכותבין לו שטר אחר מזמן ראשון\u0004 — \u0003הוה הדר ביה\u0004 \u0005[היה חוזר בו]\u0006 ופוסק כדברי ר' יהודה, כלשון הברייתא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003שמיע ליה\u0004 \u0005[שמע]\u0006 רב וידע את הברייתא הזו, \u0003ו\u0004בכל זאת \u0003לא הדר ביה\u0004 \u0005[חזר בו]\u0006 מדבריו, ומה טעמו?"],["שכן יש להבחין: \u0003בשלמא\u0004 \u0005[נניח]\u0006 במקרה המדובר במשנתנו, נעשה הדבר על ידי \u0003בי דינא\u0004 \u0005[בית דין]\u0006 שהם \u0003אלימי לאפקועי ממונא\u0004 \u0005[חזקים\u0006 דיים כדי \u0005להפקיע ממון]\u0006 ולכן הם יכולים להקדים את זמן השעבוד לפני זמן כתיבת השטר. \u0003אלא\u0004 במקרה המדובר בברייתא, \u0003עדים ש\u0004כבר \u0003עשו שליחותן\u0004 בכתיבת שטר ראשון, וכי הם \u0003חוזרין ועושין שליחותן?\u0004","ותוהים: \u0003ו\u0004האם \u0003לא\u0004 יכולים עדים לחזור ולעשות שליחותם? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר רב\u0004 עצמו: \u0003עדים כותבין אפילו עשרה שטרות על שדה אחת!\u0004","את הקושי הזה מפרשים בשתי דרכים דומות, \u0003רב יוסף אמר:\u0004 פה מדובר \u0003בשטר מתנה\u0004 שאין בו אחריות, כך שאין בו הפסד לאדם אחר.","\u0003ורבה אמר:\u0004 כותבים עשרה שטרות, אפילו שטר מכר, דווקא \u0003בשטר\u0004 \u0003שאין בו אחריות\u0004 ואינו מחייב אחרים.","ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 אותה \u0003ברייתא\u0004 שרמזו לה? ומביאים את הברייתא בשלמותה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיו נושין בו אלף זוז, ופרע מהן חמש מאות זוז,\u0004 מה עושים? — \u0003עדים מקרעין את השטר וכותבין לו שטר אחר מזמן ראשון,\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר: שטר זה\u0004 הראשון \u0003יהא מונח במקומו\u0004 כמות שהוא, \u0003ויכתבו\u0004 ללווה \u0003שובר\u0004 על מה שפרע;","\u0003ומפני שני דברים אמרו\u0004 ש\u0003כותבין שובר\u0004 ואין מקרעים את השטר: \u0003אחת\u0004 — \u0003כדי שיכוף,\u0004 שיגרום הדבר ללווה למהר ו\u0003לפורעו,\u0004 מפני שיש עליו שטר חוב בסכום גדול. \u0003ואחת\u0004 — \u0003כדי שיגבה\u0004 המלוה מנכסים שהיו ביד הלווה כבר \u0003מזמן ראשון,\u0004 ולא רק מזמן שני.","על ההסבר השני שואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהודה נמי\u0004 \u0005[גם כן]\u0006 שאמר שכותבים שטר חדש, \u0003מזמן ראשון קאמר\u0004 \u0005[הוא אומר]\u0006 שצריך לכתוב את השטר! ומשיבים: \u0003הכי קאמר ליה\u0004 \u0005[כך אומר לו]\u0006 \u0003ר' יוסי לר' יהודה: אי\u0004 \u0005[אם]\u0006 \u0003מזמן ראשון קאמרת\u0004 \u0005[אומר אתה]\u0006 שצריך לכתוב את השטר השני — \u0003פליגנא עלך בחדא\u0004 \u0005[חולק אני עליך ב\u0006דבר \u0005אחד]\u0006 בגלל סיבה אחת — כדי שיכוף לפורעו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003מזמן שני קאמרת\u0004 \u0005[אומר אתה]\u0006 שכותבים בשטר החדש — \u0003פליגנא עלך בתרתי\u0004 \u0005[חולק אני עליך בשתיים]\u0006 משתי סיבות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שטר שזמנו כתוב בשבת או בעשרה בתשרי\u0004 שהוא יום הכיפורים, ובוודאי לא נכתבו השטרות בימים אלה, שהרי אסור לכתוב בהם — \u0003שטר מאוחר הוא,\u0004 כלומר, שאיחרו את התאריך הכתוב בשטר מן הזמן שהיתה בו העיסקה באמת, \u0003וכשר\u0004 הוא, אלו \u0003דברי ר' יהודה, ר' יוסי פוסל\u0004 בשטר מאוחר. \u0003אמר לו ר' יהודה: והלא מעשה בא לפניך בצפורי\u0004 בשטר כזה \u0003והכשרת! אמר לו: כשהכשרתי\u0004 — \u0003בזה הכשרתי\u0004 כשזמנו היה בשבת או ביום הכיפורים, כשהיה ברור מתאריכו שהוא מאוחר.","ותוהים על תשובתו של ר' יוסי: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהודה נמי\u0004 \u0005[גם כן]\u0006 \u0003בזה\u0004 בשטר כזה \u0003קאמר\u0004 \u0005[הוא אומר]\u0006 שכשר, ועל מה חלק ר' יוסי?","\u0003אמר ר' פדת\u0004 בהסבר דברי הברייתא: \u0003הכל מודים, שאם הוזקקנו ל\u0004בדוק \u0003עונתו\u0004 (זמנו) \u0003של שטר,\u0004 שלא נאמר בו באיזה יום בשבוע נכתב, או באיזה יום בחודש העברי נכתב, \u0003ונמצאת עונתו מכוונת בשבת או בעשרה בתשרי ש\u0004כדברי ר' יהודה בברייתא — \u0003שטר מאוחר הוא וכשר,\u0004 לפי שמוכח מן השטר שהוא מאוחר, ואין לחשוש לתקלה."],["\u0003לא נחלקו אלא בשטר מאוחר בעלמא\u0004 \u0005[סתם],\u0006 שאין ניכר מתוכו שהוא מאוחר, ש","\u0003ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 במשנתנו, במי שפרע מקצת חובו, ש\u0003אמר: אין כותבין שובר,\u0004 אלא המלוה צריך להחזיר את השטר ללווה. \u0003ו\u0004אם כן \u0003לא נפיק מיניה חורבא\u0004 \u0005[אין יוצא מזה נזק];\u0006","\u0003ור' יוסי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: כותבין שובר\u0004 ואין מחזירים את השטר ללווה, \u0003ונפיק מיניה חורבא\u0004 \u0005[ויוצא מזה נזק]\u0006 שמא יפרע חובו לפני זמן השטר, ולא יחזיר המלוה את השטר, אלא יטען שאבד, ויכתוב שובר, ולאחר זמן יוציא את השטר ויגבה בו כאילו חזר והלוה לו בתאריך מאוחר יותר.","ובענין כתיבת שובר שנחלקו בה במשנתנו, \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003כותבין שובר,\u0004 כלומר, לדעת ר' יוסי, \u0003הני מילי אפלגא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005על מחצית],\u0006 על חלק מן הסכום, כשפרע מקצת החוב, ויש שטר על כל הסכום ביד המלוה, \u0003אבל אכוליה\u0004 \u0005[על כולו]\u0006 כגון שהמלוה טוען שהשטר אבד — \u0003לא.\u0004","ומעירים: \u0003ולא היא\u0004 (ואין הדבר כן), \u0003אפילו אכוליה כתבינן\u0004 \u0005[על כולו כותבים אנו];\u0006","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב יצחק בר יוסף הוה מסיק ביה זוזי\u0004 \u0005[היה נושה בו כסף]\u0006 \u0003בר' אבא, אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003ר' חנינא בר פפי, אמר ליה\u0004 \u0005[לו]\u0006 רב יצחק בר יוסף לר' אבא: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 את \u0003זוזיי\u0004 \u0005[מעותי],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 את \u0003שטראי\u0004 \u0005[שטרי]\u0006 \u0003ושקול זוזך\u0004 \u0005[וקח\u0006 את \u0005כספך],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שטרך אירכס\u0004 \u0005[אבד]\u0006 \u0003לי,\u0004 \u0003אכתוב לך תברא\u0004 \u0005[שובר]\u0006 שפרעת לי את כל החוב, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא בר פפי, שבאו לדון לפניו: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אין כותבין שובר!\u0004","\u0003אמר: מאן יהיב לן מעפריה\u0004 \u0005[מי יתן לנו מעפרם]\u0006 של \u0003רב ושמואל רמינן בעיינין\u0004 \u0005[\u0006ו\u0005נשים בעינינו]\u0006 מרוב הערצתנו להם, שבוודאי גדולי עולם היו, מכל מקום \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ר' יוחנן והא\u0004 \u0005[והרי]\u0006 \u0003ריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כותבין שובר.\u0004","ומעירים, \u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' אילעא: כותבין שובר.\u0004","ומעירים: \u0003ומסתברא\u0004 \u0005[ומסתבר\u0006 לומר\u0005]\u0006 ש\u0003כותבין שובר\u0004 במקרה שהמלוה טוען שאבד שטרו, ומחייבים את הלווה לפרוע את החוב, \u0003דאי סלקא דעתא\u0004 \u0005[שאם עולה על הדעת]\u0006 לומר ש\u0003אין כותבין שובר,\u0004 אם \u0003אבד שטרו של זה\u0004 של המלוה — \u0003יאכל הלה\u0004 הלווה \u0003וחדי\u0004 \u0005[וישמח]\u0006 שאינו צריך לשלם?","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003אביי: ואלא מאי\u0004 \u0005[מה]\u0006 תאמר, \u0003כותבין שובר\u0004 כשטוען המלוה שאבד שטרו? \u0003אבד שוברו של זה\u0004 — \u0003יאכל הלה\u0004 זה המלוה, שיגבה פעם שניה בשטרו, \u0003וחדי\u0004 \u0005[וישמח]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אין\u0004 \u0005[כן],\u0006 אנו צריכים לדאוג יותר למלוה מאשר ללווה, כפי שאמר הכתוב \u0003\"עבד לוה לאיש מלוה\"\u0004 (משלי כב, ז).","ובענין שטר מאוחר שנחלקו בו ר' יהודה ור' יוסי, \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת שביעית: \u0003שטרי חוב המוקדמין\u0004 שהזמן הכתוב בהם מוקדם לזמן כתיבת השטר — \u0003פסולין,\u0004 \u0003והמאוחרין כשרין.\u0004","\u0003אמר רב המנונא: לא שנו\u0004 דבר זה \u0003אלא\u0004 ב\u0003שטרי הלואה, אבל שטרי מקח וממכר\u0004 — \u0003אפילו מאוחרין נמי\u0004 \u0005[גם כן]\u0006 \u0003פסולין. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — לפי שעלול הקונה להשתמש בו שלא כדין. כיצד? — \u0003זימנין דמזבין ליה ארעא\u0004 \u0005[פעמים ש\u0006הוא \u0005מוכר לו קרקע]\u0006 \u0003בניסן, וכתיב ליה\u0004 \u0005[וכותב אותו]\u0006 את התאריך שבשטר \u0003בתשרי\u0004 שלאחר מכן, \u0003ומתרמי ליה זוזי ביני ביני וזבין ליה מיניה\u0004 \u0005[ומזדמן לו\u0006 למוכר \u0005כסף בינתיים,\u0006 וחוזר \u0005וקונה אותה ממנו].\u0006 \u0003וכי מטי\u0004 \u0005[וכאשר בא]\u0006 חודש \u0003תשרי מפיק ליה\u0004 \u0005[מוציא לו]\u0006 הקונה את השטר \u0003ואמר ליה\u0004 \u0005[ואומר לו]\u0006 למוכר: \u0003הדר זבנתה מינך\u0004 \u0005[חזרתי\u0006 ו\u0005קניתי אותה ממך]\u0006 והרי השטר המעיד על המכירה עכשיו!","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם לזה אתה חושש, \u0003שטרי הלואה נמי\u0004 \u0005[גם כן]\u0006 יש בהם מקום לחשש זה, כיצד? — \u0003זמנין דיזיף\u0004 \u0005[פעמים ש\u0006הוא \u0005לווה]\u0006 \u0003בניסן וכתיב ליה שטרא\u0004 \u0005[וכותב לו שטר]\u0006 שתאריכו \u0003בתשרי\u0004 שאחריו\u0003, ומתרמי ליה זוזי ביני ביני ופרע ליה\u0004 \u0005[ומזדמן לו\u0006 ללווה \u0005כסף בינתיים ופורע לו],\u0006 \u0003ואמר ליה\u0004 \u0005[ואומר לו]\u0006 הלווה למלוה: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 את \u0003שטראי\u0004 \u0005[שטרי],\u0006 \u0003ואמר ליה\u0004 \u0005[ואומר לו]\u0006 המלוה: \u0003אירכס\u0004 \u0005[אבד]\u0006 \u0003לי\u0004 השטר. \u0003וכתיב ליה תברא\u0004 \u0005[וכותב לו\u0006 ללווה \u0005שובר\u0006 שפרע את חובו\u0005],\u0006 אבל באמת השטר נשאר ביד המלוה. \u0003וכי מטי זמניה\u0004 \u0005[וכאשר בא זמנו]\u0006 של השטר, בתשרי, \u0003מפיק ליה\u0004 \u0005[מוציא אותו]\u0006 \u0003ואמר ליה\u0004 \u0005[ואומר לו]:\u0006 \u0003הני השתא\u0004 \u0005[\u0006מעות \u0005אלה\u0006 בשטר, \u0005עכשיו]\u0006 \u0003הוא דיזפת מינאי\u0004 \u0005[שלווית ממני]!\u0006","ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 רב המנונא: \u0003אין כותבין שובר\u0004 ואין הלווה פורע למלוה עד שיחזיר לו את שטרו, ולפיכך אין לחשוש לכך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב כהנא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב ירמיה מדיפתי לרב כהנא: והאידנא דכתבינן שטרי מאוחרי וכתבינן תברא\u0004 \u0005[ועכשיו שאנו כותבים שטרות מאוחרים וכותבים אנו\u0006 גם \u0005שוברים],\u0006 \u0003אמאי קעבדינן הכי\u0004 \u0005[מדוע עושים אנו כך]?\u0006 הרי יש מקום לחשוש! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003בתר\u0004 \u0005[אחרי]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' אבא לספריה\u0004 \u0005[לסופריו]:\u0006 \u0003כי כתביתו שטר מאוחרי, כתבו הכי\u0004 \u0005[כאשר אתם כותבים שטרות מאוחרים, כתבו כך\u0006 בתוכו\u0005]:\u0006 \u0003\"שטרא דנן\u0004 \u0005[שטר זה]\u0006 \u0003לא בזמניה כתבניה\u0004 \u0005[בזמנו כתבנוהו]\u0006 \u0003אלא אחרנוהו וכתבנוהו\".\u0004 ולכן אין לחשוש, לפי שאם יבוא המלוה לתבוע שנית — יאמר לו שכבר נפרע, כי היה זה שטר מאוחר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: והאידנא דלא קא עבדינן הכי\u0004 \u0005[ועכשיו שאין אנו עושים כך]\u0006 ואין כותבים נוסח זה בשטר מאוחר, מדוע אנו עושים כן? והרי יש חשש לרמאות! אמר לו: \u0003בתר\u0004 \u0005[אחרי]\u0006 ש\u0003אמר ליה\u0004 \u0005[להם]\u0006 \u0003רב ספרא לספריה\u0004 \u0005[לסופריו]:\u0006 \u0003כי כתביתו הני תברי\u0004 \u0005[כאשר אתם כותבים\u0006 את אלו \u0005השוברים],\u0006 \u0003אי ידעיתו זימנא דשטרא\u0004 \u0005[אם אתם יודעים\u0006 את \u0005זמן השטר]\u0006 — \u0003כתבו\u0004 ששובר זה נכתב עבור פרעון שטר שנכתב בזמן פלוני, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא,\u0004 אם אינכם יודעים את התאריך — \u0003כתבו סתמא\u0004 \u0005[\u0006שובר \u0005סתם],\u0006 \u0003דכל אימת דנפיק\u0004 \u0005[שכל זמן שיצא\u0006 עליו השטר\u0005]\u0006 — \u0003לרעיה\u0004 \u0005[ירע אותו\u0006 השובר הזה\u0005].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אשי לרב כהנא:\u0004"],["\u0003והא האידנא דלא קעבדינן הכי\u0004 \u0005[והרי עכשיו שאין אנו עושים כך]\u0006 וכותבים שטר מאוחר סתם, בלא לציין שהוא מאוחר, וגם כותבים תאריך בשובר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רבנן תקוני תקיני\u0004 \u0005[חכמים תיקנו]\u0006 לעשות כמו שאמר רב ספרא, \u0003מאן דעביד\u0004 \u0005[מי שעושה]\u0006 — \u0003עביד\u0004 \u0005[עושה]\u0006 כראוי, \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003לא עביד\u0004 — \u0003איהו הוא דאפסיד אנפשיה\u0004 \u0005[הוא זה שגורם הפסד לעצמו].\u0006","ועוד בענין כתיבה של שטר שלא בזמנו \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא בר רב שילא להנהו כתבי שטרא אקניאתא\u0004 \u0005[לאלה\u0006 ש\u0005כותבים שטרי הקנייה]:\u0006 \u0003כי כתביתו שטרי אקניאתא\u0004 \u0005[כאשר אתם כותבים\u0006 לאחר זמן \u0005שטרי הקנייה],\u0006 כלומר, שטר על דבר שנעשה בו קנין, \u0003אי ידעיתו יומא דקניתו ביה\u0004 \u0005[אם יודעים אתם\u0006 את \u0005היום שבו\u0006 \u0005עשיתם\u0006 את \u0005הקנין]\u0006 — \u0003כתבו, ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שאין אתם יודעים מה היה אותו יום — \u0003כתבו יומא דקיימיתו ביה\u0004 \u0005[\u0006את \u0005היום שאתם עומדים בו],\u0006 \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא מתחזי כשקרא\u0004 \u0005[ייראה\u0006 הדבר \u0005כשקר],\u0006 שלא יכתבו תאריך שלא היה בו המעשר כלל.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב לספריה\u0004 \u0005[לסופריו],\u0006 \u0003וכן אמר להו\u0004 \u0005[להם]\u0006 \u0003רב הונא לספריה\u0004 \u0005[לסופריו]:\u0006 \u0003כי קיימיתו\u0004 \u0005[כאשר אתם נמצאים]\u0006 \u0003ב\u0004מקום הנקרא \u0003שילי\u0004 — \u0003כתבו\u0004 בשטר שהוא נכתב \u0003בשילי\u0004\u0005,\u0006 \u0003ואף על גב דמסירן לכו מילי\u0004 \u0005[ואף על פי שנמסרו לכם הדברים]\u0006 \u0003בהיני\u0004 הסמוכה לה. \u0003כי קיימיתו\u0004 \u0005[כאשר אתם נמצאים]\u0006 \u0003בהיני כתבו בהיני,\u0004 \u0003ואף על גב דמסירן לכו מילי\u0004 \u0005[ואף על פי שנמסרו לכם הדברים]\u0006 \u0003בשילי.\u0004","\u0003אמר רבא: האי מאן דנקיט שטרא בר מאה זוזי\u0004 \u0005[מי שמחזיק בידו שטר\u0006 חוב \u0005של מאה זוז],\u0006 \u0003ואמר\u0004 \u0005[ואומר]:\u0006 \u0003שויה ניהלי תרי\u0004 \u0005[עשה לי שני]\u0006 שטרות \u0003בני חמשין חמשין\u0004 \u0005[חמישים חמישים],\u0006 כדי שאם יפרע לי הלווה מחצית יישאר בידי שטר מתאים — \u0003לא משוינן להו\u0004 \u0005[עושים אותם].\u0006","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003עבדו רבנן מילתא דניחא ליה\u0004 \u0005[עשו חכמים\u0006 בהוראה זו \u0005דבר שנוח לו]\u0006 \u0003למלוה וניחא ליה\u0004 \u0005[ונוח לו]\u0006 \u0003ללוה,\u0004 כיצד? — \u0003ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003למלוה\u0004 — \u0003כדי שיכוף לפורעו,\u0004 שכשיש שטר גדול הלווה חושש יותר וממהר לפרוע אותו, \u0003וניחא\u0004 \u0005[ונוח\u0006 לו\u0005]\u0006 \u0003ללוה\u0004 — \u0003כי היכי דניפגם שטריה\u0004 \u0005[כדי שייפגם שטרו]\u0006 של המלוה לאחר שישלם חלק ממנו. שאין נפרעים בשטר כזה אלא בשבועה.","\u0003ו\u0004מן הצד השני \u0003אמר רבא: האי מאן דנקיט תרי שטרי\u0004 \u0005[מי שמחזיק\u0006 בידו \u0005שני שטרות]\u0006 על אדם אחד \u0003בני חמשין חמשין\u0004 \u0005[חמישים חמישים],\u0006 \u0003ואמר\u0004 \u0005[אומר]:\u0006 \u0003שוינהו ניהלי חד\u0004 \u0005[עשו אותם לי\u0006 שטר \u0005אחד]\u0006 \u0003בר\u0004 \u0005[בן]\u0006 \u0003מאה\u0004 \u0003—\u0004 \u0003לא משוינן ליה\u0004 \u0005[אין אנו עושים לו],\u0006 ומסבירים: מה טעם הדבר?","— \u0003עבוד רבנן מילתא דניחא ליה\u0004 \u0005[עשו חכמים\u0006 בהוראה זו \u0005דבר שנוח לו]\u0006 \u0003למלוה וניחא ליה\u0004 \u0005[ונוח לו]\u0006 \u0003ללוה; ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003למלוה\u0004 — \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ניפגום שטריה\u0004 \u0005[ייפגם שטרו],\u0006 שאם פורע חצי הסכום, יישאר בידו שטר שאינו פגום, על החצי השני, \u0003וניחא ליה\u0004 \u0005[ונוח לו]\u0006 \u0003ללוה\u0004 — \u0003כדי ש\u0004אם יפרע את מחצית הסכום \u0003לא יכוף לפורעו\u0004 בשטר הקודם, שיש בו סכום גדול יותר ממה שהוא באמת חייב לו.","\u0003אמר רב אשי: האי מאן דנקיט שטרא בר מאה זוזי\u0004 \u0005[מי שמחזיק שטר בן מאה זוז],\u0006 \u0003ואמר\u0004 \u0005[ואומר]:\u0006 החייב שילם לי מחצית, \u0003שוונהי ניהלי חד בר חמשין\u0004 \u0005[עשו אותו לי\u0006 שטר \u0005אחד בן,\u0006 של \u0005חמישים]\u0006 — \u0003לא משוינא ליה\u0004 \u0005[אין אנו עושים לו].\u0006","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003האי מיפרע פרעיה\u0004 \u0005[\u0006שטר \u0005זה פרע אותו]\u0006 החייב, ובאותו זמן שפרעו \u0003אמר ליה\u0004 \u0005[לו]\u0006 הלווה: \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 את \u0003שטראי\u0004 \u0005[שטרי],\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 המלוה: \u0003אירכס\u0004 \u0005[אבד]\u0006 \u0003לי, וכתיב ליה תברא\u0004 \u0005[וכתב לו\u0006 המלוה \u0005שובר],\u0006 \u0003ו\u0004יש לחשוש שמא \u0003מפיק ליה האי\u0004 \u0005[יוציא לו\u0006 את \u0005זה]\u0006 השטר החדש שכתבו לו \u0003ואמר ליה\u0004 \u0005[ויאמר לו]:\u0006 \u0003האי אחרינא הוא\u0004 \u0005[זה שטר\u0006 אחר \u0005הוא],\u0006 של הלוואה אחרת שלווית.","\u0003שני אחין, אחד\u0004 מהם \u0003עני ואחד עשיר, והניח להן אביהן\u0004 בירושה \u0003מרחץ ובית הבד\u0004 שסוחטים בו את הזיתים לעשיית שמן, אם \u0003עשאן\u0004 אביהם \u0003לשכר,\u0004 כלומר, עשה את המרחץ ובית הבד הללו על מנת להשכיר אותם לאחרים — \u0003השכר לאמצע,\u0004 והאחים מתחלקים בשכר הזה בשווה, כשותפים בו. אם \u0003עשאן לעצמו\u0004 שלא על מנת להשכיר, אלא רק לשימוש עצמי — \u0003הרי העשיר אומר לעני: \"קח לך עבדים וירחצו במרחץ\", \"קח לך זיתים ובא ועשה בבית הבד\",\u0004 ואין העני יכול לומר שכיון שאין לו צורך בדבר — ישכירו את המרחץ ואת בית הבד לאחרים ויתחלקו בשכר.","\u0003שנים שהיו בעיר אחת, שם אחד יוסף בן שמעון ושם אחר יוסף בן שמעון,\u0004 כלומר, שהיו שניהם בעלי שמות שווים — \u0003אין יכולין להוציא שטר חוב זה על זה,\u0004 שהרי אין זה ברור מי הוא הלווה ומי המלוה. \u0003ו\u0004כן \u0003לא אחר יכול להוציא עליהן שטר חוב,\u0004 שהרי כל אחד מהם יכול לטעון שלא הוא הלווה אלא האחר.","אם \u0003נמצא לאחד\u0004 אחר \u0003בין שטרותיו\u0004 רשום ש\u0003שטרו של יוסף בן שמעון פרוע\u0004 — ה\u0003שטרות\u0004 של \u0003שניהן פרועין,\u0004 שכל אחד מהם יכול לטעון שהוא יוסף בן שמעון שנפרע שטרו.","\u0003כיצד יעשו\u0004 כדי שיוכלו לנהל משא ומתן? — \u0003ישלשו,\u0004 כלומר, יוסיפו דור שלישי לשם יוסף בן שמעון, שיכתבו גם בן פלוני, כך שיהיה הבדל בין זה לזה, \u0003ואם היו משולשין\u0004 שגם שמות הסבים היו שווים — \u0003יכתבו סימן,\u0004 כגון שאחד נמוך והאחר גבוה, \u0003ואם היו מסומנין\u0004 באותו סימן — \u0003יכתבו\u0004 סימן זיהוי אחר, כגון שפלוני הוא \u0003כהן.\u0004","\u0003ההוא שטרא דנפק לבי דינא\u0004 \u0005[שטר אחד שיצא לפני בית הדין]\u0006 של \u0003רב הונא, דהוה כתיב ביה\u0004 \u0005[שהיה כתוב בו]\u0006 \u0003\"אני פלוני בר\u0004 \u0005[בן]\u0006 \u0003פלוני לויתי מנה ממך\",\u0004 ולא היה כתוב בו שם המלוה,"],["\u0003אמר רב הונא:\u0004 הלשון \u0003\"ממך\"\u0004 הכתובה בשטר — הריהי כוללת כל אדם, \u0003אפילו מריש גלותא\u0004 \u0005[מראש הגלות],\u0006 \u0003ואפילו משבור מלכא\u0004 \u0005[המלך],\u0006 שכל אדם שמחזיק את השטר יכול לתבוע אותו, ואין לומר שמא לא הוא זה שהלוה את הכסף.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרבה: פוק\u0004 \u0005[צא]\u0006 \u0003עיין בה\u0004 בהלכה זו, משום \u0003דלאורתא בעי לה\u0004 \u0005[שבערב ישאל אותה]\u0006 \u0003רב הונא מינך\u0004 \u0005[ממך]\u0006 מה אתה סבור בענין זה.","\u0003נפק דק ואשכח\u0004 \u0005[יצא דקדק ומצא],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003גט שיש עליו עדים ואין בו זמן, אבא שאול אומר: אם כתוב בו \"גרשתיה היום\"\u0004 — \u0003כשר;\u0004","\u0003אלמא\u0004 \u0005[מכאן יוצא]\u0006 ש\u0003\"היום\"\u0004 — \u0003ההוא יומא דנפיק ביה משמע\u0004 \u0005[אותו יום שיוצא בו\u0006 הגט \u0005משמעו]\u0006 ודי בכך, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בשטר, \u0003\"ממך\"\u0004 — \u0003מההוא גברא דנפיק מתותי ידיה\u0004 \u0005[מאותו אדם שיצא מתחת ידו]\u0006 \u0003משמע.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ודלמא\u0004 \u0005[ושמא]\u0006 \u0003אבא שאול\u0004 שהכשיר גט שאין בו תאריך מוגדר, \u0003כר' אליעזר סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר: עדי מסירה\u0004 שראו מסירת הגט לאשה \u0003כרתי\u0004 \u0005[\u0006הם \u0005הכורתים\u0006 שהגט\u0005],\u0006 ולכן הוא כשר גם אם אין כתוב בו אלא נוסח סתמי, \u0003אבל הכא ליחוש\u0004 \u0005[כאן נחשוש]\u0006 \u0003לנפילה,\u0004 שמא נפל השטר מיד המלוה ומצאו אחר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003לנפילה\u0004 של שטר מיד המלוה \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006 \u0003ומנא תימרא דלא חיישינן\u0004 \u0005[ומנין אתה אומר שאין אנו חוששים]\u0006 \u0003לנפילה?\u0004","— \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שנים שהיו בעיר אחת, שם אחד יוסף בן שמעון ושם אחר יוסף בן שמעון\u0004 — \u0003אינן יכולין להוציא שטר חוב זה על זה,\u0004 משום שלא ברור מן השטר מי הוא המלוה ומי הוא הלווה, \u0003ולא אחר יכול להוציא עליהן שטר חוב,\u0004 שהרי כל אחד מהם יכול לטעון שלא הוא הלווה אלא חבירו. ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003הם על אחרים\u0004 — \u0003יכולין\u0004 להוציא שטר חוב. ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003ליחוש\u0004 \u0005[שנחשוש]\u0006 \u0003לנפילה!\u0004 שמא היה השטר בעצם שייך ליוסף בן שמעון האחר, ונפל ממנו השטר, ומצאו יוסף בן שמעון זה, והוא גובה בו! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003לנפילה לא חיישינן\u0004 \u0005[אין אנו חוששים]?\u0006","\u0003ואביי,\u0004 מה עונה הוא על כך? — לדעתו יש לחלק: \u0003לנפילה דחד לא חיישינן\u0004 \u0005[של אחד אין אנו חוששים],\u0006 כלומר, שיפול השטר מאדם מסויים זה, ויגיע דווקא לידי אותו אדם ששמו כשמו — אין אנו חוששים, אבל \u0003לנפילה\u0004 של \u0003רבים,\u0004 כגון שטר \"ממך\", שיכול היה ליפול מכל אדם, וכל אדם שמוצא את השטר יכול להשתמש בו — \u0003חיישינן\u0004 \u0005[אנו חוששים].\u0006"],["ושואלים: \u0003ואלא הא\u0004 \u0005[זו]\u0006 שיטה אחרת החולקת על משנתנו \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשם שאין\u0004 שני יוסף בן שמעון \u0003מוציאין שטר חוב זה על זה\u0004 — \u0003כך אין מוציאין על אחרים,\u0004 אם כן \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]\u0006 שני התנאים? מדוע סבור כן התנא שבברייתא? והרי אמרנו שאין חוששים לנפילה של שטר מאדם אחד!","ומשיבים: \u0003ב\u0004שאלה האם \u0003אותיות\u0004 (שטרות) \u0003נקנות במסירה קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 ובאופן זה: ה","\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 \u0003סבר\u0004 \u0005[סבור]\u0006 ש\u0003אותיות נקנות במסירה,\u0004 ולכן, גם אם לא נחשוש לנפילה, ייתכן שהמלוה יוסף בן שמעון מסר את השטר ליוסף בן שמעון השני, והואיל והשטר נקנה לו במסירה הוא רשאי לגבותו. \u0003ו\u0004ה\u0003תנא ברא סבר\u0004 \u0005[החיצון,\u0006 של הברייתא, \u0005סבור]\u0006 ש\u0003אין אותיות נקנות במסירה,\u0004 והלווה יכול לטעון למחזיק בשטר: שמא יוסף בן שמעון האחר מסר לך את השטר, ולא זכית בו כלל.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהסבר המחלוקת הוא באופן אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 — \u0003אותיות נקנות במסירה, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003צריך להביא ראיה\u0004 שאכן קנה את השטר \u0003קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 ובאופן זה: ה\u0003תנא דידן סבר\u0004 \u0005[שלנו,\u0006 במשנתנו, \u0005סבור]\u0006 ש\u0003אין צריך להביא ראיה,\u0004 ומניחים שהשטר שבידי מחזיק השטר — שלו הוא, \u0003ו\u0004ה\u0003תנא ברא סבר\u0004 \u0005[החיצון,\u0006 בברייתא, \u0005סבור]\u0006 ש\u0003צריך להביא ראיה\u0004 שהקנה לו את השטר, ואינו בידו כפקדון. ומנין שיש מחלוקת כזאת?","— \u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003אותיות נקנות במסירה, אביי אמר: צריך\u0004 על כל פנים \u0003להביא ראיה\u0004 שנמסר בידו השטר הזה, \u0003ורבא אמר: אינו צריך להביא ראיה.\u0004","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 את דעתי זו? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד מן האחין שהשטר חוב\u0004 של אביו \u0003יוצא מתחת ידו,\u0004 והוא טוען שהאב נתן לו שטר זה — \u0003עליו להביא ראיה\u0004 שהגיע לידו השטר כדין. ומכאן מוסיף אביי: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נלמד מכאן ש\u0003הוא הדין לאחריני\u0004 \u0005[לאחרים]?\u0006 שלא רק אחד מן האחים, אלא כל מי ששטר של אדם אחר יוצא מתחת ידו, צריך להביא ראיה שהלה הקנה לו את השטר?","\u0003ורבא אמר:\u0004 אין הדברים דומים, \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003אחין,\u0004 שעל זה המחזיק בשטר להביא ראיה לאחיו, מפני \u0003דשמטו מהדדי\u0004 \u0005[ש\u0006הם \u0005שומטים,\u0006 נוטלים \u0005זה מזה]\u0006 שהרי הם מצויים במקום אחד, וגם יש להם תביעות זה על זה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שמביאים את הדיון הזה בלשון אחרת, \u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אני אומר\u0006 את דעתי \u0005זו]\u0006 שהטוען שקנה שטר מיד האחר אינו צריך להביא ראיה? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד מן האחין שהשטר חוב יוצא מתחת ידו\u0004 — \u0003עליו להביא ראיה.\u0004 ונדייק מכאן: דווקא ב\u0003אחין\u0004 כך \u0003הוא\u0004 הדין, משום \u0003דשמטו מהדדי\u0004 \u0005[ש\u0006הם \u0005שומטים זה מזה]\u0006 ולכן צריכים להביא ראיה, \u0003אבל אחריני\u0004 \u0005[אחרים]\u0006 \u0003לא.\u0004","\u0003ואביי,\u0004 מהו הוא עונה על כך? — לדעתו הוא הדין לכל אדם, ואולם \u0003אחין איצטריכא ליה\u0004 \u0005[\u0006\u0005הוצרך\u0006 \u0005לו\u0006 לומר\u0005]\u0006 ולהדגיש שגם בהם שייך דין זה, ומדוע? — \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003כיון דשמטו מהדדי\u0004 \u0005[ש\u0006הם \u0005שומטים זה מזה]\u0006 — \u0003אימא מיזדהר זהירי\u0004 \u0005[אמור שזהירים הם\u0006 יותר\u0005]\u0006 להישמר זה מזה, \u0003ולא צריכי\u0004 \u0005[ואינם צריכים]\u0006 \u0003להביא ראיה\u0004 על שטר בידם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו אלה צריכים להביא ראיה.","לעיל הבאנו ברייתא החולקת על משנתנו, והסברנו באיזו נקודה הם חלוקים. ושואלים: \u0003ואלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]\u0006 שיש בה שיטה שלישית, שגם היא חולקת על משנתנו: \u0003כשם שמוציאין הן\u0004 שני יוסף בן שמעון \u0003שטר חוב על אחרים\u0004 — \u0003כך מוציאין זה על זה,\u0004 ואם כן \u0003במאי קמיפלגי\u0004 \u0005[במה חלוקים הם]\u0006 תנא זה והתנא של משנתנו, שהוא סבור שאף שהם יכולים להוציא על אחרים — אינם יכולים להוציא זה על זה? מהו בסיס המחלוקת?","ומשיבים: \u0003ב\u0004שאלה האם \u0003כותבין שטר ללוה ואף על פי שאין מלוה עמו קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 ובאופן זה: ה","\u0003תנא דידן סבר\u0004 \u0005[שלנו סבור]\u0006 ש\u0003כותבין שטר ללוה ואף על פי שאין מלוה עמו,\u0004 ולכן יש לחשוש, כיצד? \u0003זימנין דאזיל לגבי ספרא וסהדי\u0004 \u0005[פעמים שהולך\u0006 יוסף בן שמעון אחד \u0005אצל הסופר והעדים],\u0006 \u0003ואמר להו\u0004 \u0005[ואומר להם]:\u0006 \u0003כתבו לי שטרא\u0004 \u0005[שטר],\u0006 \u0003דבעינן למיזף\u0004 \u0005[שאני רוצה ללוות]\u0006 \u0003מיוסף בן שמעון חברי. ובתר דכתבי וחתמי ליה\u0004 \u0005[ואחרי שכותבים וחותמים לו],\u0006 \u0003נקיטא ליה ואמר ליה\u0004 \u0005[מחזיק אותו ואומר לו\u0006 לחבירו\u0005]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי מאה\u0004 זוזים \u0003דיזפת מינאי\u0004 \u0005[שלווית ממני],\u0006 שהרי כתוב בשטר שיוסף בן שמעון חייב כסף ליוסף בן שמעון, ואני הוא המלוה, שהשטר בידי.","ואילו ה\u0003תנא ברא סבר\u0004 \u0005[החיצון,\u0006 בברייתא, \u0005סבור]\u0006 ש\u0003אין כותבין שטר ללוה עד שיהא מלוה עמו,\u0004 ואם באים שני יוסף בן שמעון אלה יחד לכתוב שטר, משמע שאינם חוששים לרמאות, ולכן הם יכולים להוציא שטר חוב זה על זה.","שנינו במשנה שאם \u0003נמצא לאחד בין שטרותיו\u0004 שובר שרשום בו כך: \u0003\"שטרו של יוסף בן שמעון פרוע\"\u0004 — \u0003שטרות שניהם\u0004 נחשב \u0003פרועין.\u0004 ומדקדקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003נמצא\u0004 כתוב כך הדין כן, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא נמצא\u0004 — \u0003מצי מפיק\u0004 \u0005[יכול\u0006 אדם \u0005להוציא]\u0006 על אחד מהם שטר חוב ששם הלווה שבו יוסף בן שמעון. ומתקשים: \u0003והאנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"ולא אחר יכול להוציא עליהן שטר חוב\" תנן\u0004 \u0005[שנינו]\u0006 קודם לכן במשנה, וגם בלא שובר!","\u0003אמר ר' ירמיה:\u0004 כאן, שיכול להוציא עליהם שטר חוב (אלמלא השובר) מדובר \u0003ב\u0004שטרי חוב \u0003משולשין,\u0004 שכתוב בהם גם שם אבי האב של יוסף בן שמעון. ומעתה אין עוד ספק מי הוא אותו יוסף בן שמעון.","ושואלים: אם כן, מדוע כשיש שובר שטרות שניהם פרועים? \u0003ונחזי תברא בשמא דמאן דכתיב\u0004 \u0005[ונראה\u0006 את \u0005השובר בשמו של מי\u0006 הוא \u0005כתוב]\u0006\u0005!\u0006 \u0003אמר רב הושעיא:\u0004 מדובר כאן \u0003במשולשין בשטר,\u0004 אבל \u0003אין משולשין בשובר,\u0004 שבשובר לא היה כתוב שם הסב, אלא \"יוסף בן שמעון\" בלבד, ולכן אפשר לפרשו על שני האנשים.","\u0003אביי אמר,\u0004 יש דרך אחרת לתרץ את הסתירה במשנה: אין מדובר כאן במלוה שהלוה לשני יוסף בן שמעון. אלא במי שלוה מהם, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003נמצא ללוה בין שטרותיו\u0004 שובר שכתוב בו \u0003\"שטרו של יוסף בן שמעון\u0004 ש\u0003עלי,\u0004 שהייתי חייב לו, \u0003פרוע\"\u0004 — \u0003שטרות שניהם פרועין,\u0004 שכאשר יבוא כל אחד משני יוסף בן שמעון אלה לתבוע ממנו — יראה לו את השובר ויאמר ששטרו שלו פרוע.","שנינו במשנה שאם היו שמותיהם ושמות אבותיהם שווים אי אפשר להם לעסוק זה עם זה. \u0003כיצד יעשו?\u0004 — \u0003ישלשו\u0004 יכתבו שמות אבות אבותיהם. ואם גם שמות אבות האבות שווים — יכתבו סימן מסויים שיש באחד מהם. ואם הסימנים בשניהם שווים — שיכתבו אם אחד מהם הוא כהן. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003אם היו שניהם כהנים,\u0004 כך שאי אפשר להבחין גם על ידי זה — \u0003יכתבו דורות,\u0004 כלומר, יוסיפו עוד דורות (דור רביעי וכו'), שהרי לא ייתכן שיהיו שמות האבות שווים במשך כל הדורות.","אב \u0003האומר לבנו \"שטר בין שטרותי פרוע,\u0004 כלומר, שטר אחד יש בידי שקיבלתי כבר את תמורתו, אבל \u0003איני יודע אי זהו\"\u0004 — \u0003שטרות כולן,\u0004 של כל האנשים נמצאים שם, נחשבים \u0003פרועין,\u0004 שהרי לא ברור איזה שטר הוא הפרוע. \u0003נמצא לאחד שם שנים,\u0004 אם היו בין שטרותיו שני שטרות של אדם אחד — כיון שאמר שרק שטר אחד פרוע — \u0003הגדול\u0004 שבהם \u0003פרוע, והקטן אינו פרוע.\u0004","\u0003אמר רבא:\u0004 האומר לחבירו: \u0003\"שטר לך בידי\u0004 שהוא \u0003פרוע\"\u0004 ויש לו עליו שני שטרות \u0003—\u0004 \u0003הגדול\u0004 מהם \u0003פרוע, והקטן אינו פרוע.\u0004 ואם הוא אומר \u0003\"חוב לך בידי\u0004 שהוא \u0003פרוע\",\u0004 משמע כל החוב, גם אם הוא בשטרות רבים, ולכן \u0003—\u0004 ה\u0003שטרות כולן פרועין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: אלא מעתה,\u0004 נאמר לפי זה שאם הוא כותב בשטר מכירה: \u0003\"שדי מכורה לך\"\u0004 — \u0003שדה גדולה\u0004 שבין שדותיו \u0003מכורה לו,\u0004 ואם הוא אומר בלשון כללית \u0003\"שדה שיש לי מכורה לך\"\u0004 — \u0003כל שדותיו מכורין לו!\u0004","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003יד בעל השטר על התחתונה,\u0004 והקונה שהוא מחזיק בשטר המכירה אינו יכול לקבל אלא את המועט ביותר. ומאותה סיבה עצמה, המלוה שיש בידו שטרות שונים — אינו יכול להשתמש אלא בקטן מביניהם, והגדול הוא הפרוע.","\u0003המלוה את חבירו על ידי ערב,\u0004 כלומר, כאשר אדם אחר ערב לחוב זה — \u0003לא יפרע מן הערב,\u0004 עד שיתבע את החייב תחילה."],["\u0003ואם אמר לו\u0004 המלווה לערב \u0003\"\u0004הריני מלוה \u0003על מנת שאפרע ממי שארצה\"\u0004 — במקרה זה \u0003יפרע\u0004 אפילו \u0003מן הערב. רבן שמעון בן גמליאל אומר: אם יש נכסים ללוה\u0004 — \u0003בין כך ובין כך,\u0004 אפילו כתב \"על מנת שאפרע ממי שארצה\" — \u0003לא יפרע מן הערב.\u0004","\u0003וכן היה רבן שמעון בן גמליאל אומר: הערב לאשה בכתובתה, והיה בעלה מגרשה\u0004 — \u0003ידירנה\u0004 הבעל \u0003הנאה,\u0004 כך שלא יוכל לשאתה שוב. והוא מחשש \u0003שמא יעשו\u0004 ביניהם הבעל והאישה \u0003קנוניא על נכסים של זה,\u0004 שהבעל יטען אחר כך שאין לו נכסים לשלם בהם את כתובתה, וישלם לה הערב את דמי הכתובה, \u0003ו\u0004אחר כך \u0003יחזיר\u0004 הבעל \u0003את אשתו\u0004 ובידה הכסף שקיבלה מן הערב.","מתחילה הבינו שהאמור במשנה ש\"לא ייפרע מן הערב\" כוונתו שלא ייפרע כלל מן הערב. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 מפני שיכול הערב לטעון למלוה: \u0003גברא אשלימת לי, גברא אשלימי לך\u0004 \u0005[אדם מסרת בידי, אדם מסרתי בידך].\u0006 כלומר, אני בסך הכל ערב לכך שהאיש הזה, הלווה, לא יברח, שאם יברח אשלם לך, והרי הוא נמצא לפניך!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן: האי דינא דפרסאי\u0004 \u0005[זה דינם של פרסים\u0006 הוא\u0005]!\u0006","ותוהים על דברי רב נחמן: \u0003אדרבה,\u0004 הפרסים \u0003בתר ערבא אזלי\u0004 \u0005[אחר הערב\u0006 הם \u0005הולכים\u0006 וגובים ממנו\u0005]\u0006, שלא כמשנה\u0005!\u0006","\u0003אלא,\u0004 כוונתו של רב נחמן היא, שדין זה שאין נפרעים מן הערב, הוא כדינם של \u0003בי דינא דפרסאי דלא יהבי טעמא למילתייהו\u0004 \u0005[בית דין של פרסים, שאינם נותנים טעם לדבריהם],\u0006 אלא פוסקים לפי רצונם, בלא טעם ראוי.","\u0003אלא\u0004 \u0003אמר רב נחמן: מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"לא יפרע מן הערב\"?\u0004 הכוונה היא ש\u0003לא יתבע\u0004 את ה\u0003ערב תחלה,\u0004 אלא יתבע קודם מן הלווה.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003המלוה את חבירו על ידי ערב\u0004 — \u0003לא יתבע ערב תחלה, ואם אמר \"על מנת שאפרע ממי שארצה\"\u0004 — \u0003יתבע\u0004 אם רוצה אף את ה\u0003ערב תחלה.\u0004","ודנים במקורו של דין הערבות. \u0003אמר רב הונא: מנין לערב\u0004 שהוא \u0003משתעבד\u0004 לתשלום באמירה בלבד? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אנכי אערבנו מידי תבקשנו\"\u0004 (בראשית מג, ט), הרי שיכול לדרוש את הדבר מיד הערב.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חסדא: הא\u0004 \u0005[זו]\u0006 אינה ערבות פשוטה, אלא ערבות מיוחדת של \u0003קבלנות היא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תנה אתו על ידי ואני אשיבנו\"\u0004 (שם מב, לז), כלומר, הוא מקבל על עצמו את כל האחריות, ולכך יש דין שונה!","\u0003אלא אמר ר' יצחק, מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה, שנאמר: \u0003\"לקח בגדו כי ערב זר ובעד נכריה חבלהו\"\u0004 (משלי כ, טז), הרי שיש רשות לקחת ממי שערב לאחר.","\u0003ואומר: \"בני אם ערבת לרעך תקעת לזר כפיך, נוקשת באמרי פיך נלכדת באמרי פיך, עשה זאת אפוא בני והנצל כי באת בכף רעך לך התרפס ורהב רעיך\"\u0004 (משלי ו, א –ג), ומפרשים פסוקים אלה שהם מדברים בשני מקרים: \"אם ערבת לרעך\" — \u0003אם ממון יש\u0004 \u0003לו בידך,\u0004 כלומר, שאתה חייב לו ממון מפני שאתה ערב לו — \u0003התר לו פיסת יד\u0004 (\"התרפס\"), כלומר, פתח לו את ידך ותן מה שאתה חייב. \u0003ואם לאו,\u0004 אם לא ממון הוא, אלא שפגעת בו (\"נוקשת באמרי פיך\") — \u0003הרבה עליו\u0004 (\"רהב\") \u0003ריעים\u0004 שיבואו ויפייסו אותו.","ועוד ביסודו של דין הערבות, \u0003אמר אמימר: ערב\u0004 ש\u0003משתעבד\u0004 לשלם חובו של חבירו אם חבירו לא ישלם, הוא תלוי ב\u0003מחלוקת ר' יהודה ור' יוסי; לר' יוסי\u0004 ש\u0003אמר: אסמכתא קניא\u0004 \u0005[קונה],\u0006 כלומר, אם אדם מבטיח ממון לחבירו אם יקרה כך וכך, אף שהוא סבור שלא יצטרך לשלם בפועל — הרי זה קנין ושעבוד — לדעתו גם ה\u0003ערב משתעבד,\u0004 ואילו \u0003ל\u0004דעת \u0003ר' יהודה\u0004 ש\u0003אמר: אסמכתא לא קניא\u0004 \u0005[אינה קונה]\u0006 — גם \u0003ערב לא משתעבד.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר: הא\u0004 \u0005[הרי]\u0006 \u0003מעשים בכל יום,\u0004 שאנו פוסקים ש\u0003אסמכתא לא קניא\u0004 \u0005[אינה קונה]\u0006 \u0003ו\u0004בכל זאת \u0003ערב משתעבד!\u0004","\u0003אלא אמר רב אשי:\u0004 שלא ככל הבטחה, שאין בה כדי לשעבד, הרי בערבות, \u0003בההוא\u0004 \u0005[באותה]\u0006 \u0003הנאה דקא מהימן ליה\u0004 \u0005[שהוא,\u0006 המלוה, \u0005מאמין לו]\u0006 וסומך עליו כדי להלוות ללווה — \u0003גמר\u0004 \u0005[גומר]\u0006 הערב בלבו \u0003ומשתעבד נפשיה\u0004 \u0005ומשעבד עצמו]\u0006 לענין זה.","שנינו במשנה: \u0003\"ואם אמר על מנת שאפרע ממי שארצה\"\u0004 — ייפרע מן הערב. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: לא שנו\u0004 שנפרע מן הערב, \u0003אלא\u0004 בזמן \u0003שאין נכסים ללוה, אבל\u0004 אם \u0003יש נכסים ללוה\u0004 — \u0003לא יפרע מן הערב.\u0004","ותוהים: \u0003והא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנינו בסופה\u0006 של המשנה\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: אם יש נכסים ללוה\u0004 — \u0003לא יפרע מן הערב, מכלל\u0004 הדבר אתה למד כי ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003לא שנא הכי ולא שנא הכי\u0004 \u0005[אינו שונה כך ואינו שונה כך],\u0006 בין שיש נכסים ללווה ובין שאין לו נכסים, יכול להיפרע מן הערב!","ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה המשנה וכך\u0006 היא \u0005שנויה]:\u0006 \u0003המלוה את חבירו על ידי ערב\u0004 — \u0003לא יפרע מן הערב. ואם אמר \"על מנת שאפרע ממי שארצה\"\u0004 — \u0003יפרע מן הערב. במה דברים אמורים\u0004 — \u0003בשאין נכסים ללוה, אבל\u0004 אם \u0003יש נכסים ללוה\u0004 — \u0003לא יפרע מן הערב. ו\u0004אם היה הערב \u0003קבלן,\u0004 שהוא מקבל על עצמו את פרעון החוב כאילו הוא לווה אותו, הרי \u0003אף על פי שיש נכסים ללוה\u0004 — \u0003יפרע מן הקבלן.\u0004"],["ועל כך \u0003רבן שמעון בן גמליאל אומר: אם יש נכסים ללוה\u0004 — \u0003אחד זה ואחד זה,\u0004 כלומר, אפילו קבלן, \u0003לא יפרע מהן\u0004 אלא מנכסי הלווה.","ובמסקנת ההלכה לענין זה, מביאים את מה ש\u0003אמר רבה בר חנה אמר ר' יוחנן: כל מקום ששנה רבן שמעון בן גמליאל במשנתנו\u0004 — \u0003הלכה כמותו, חוץ מ\u0004שלושה דברים: \u0003ערב,\u0004 כלומר, ההלכה האמורה כאן, שמלוה יכול להיפרע מערב למרות שיש נכסים ללווה, \u0003וצידון,\u0004 כלומר, בהלכה שנידונה אגב מעשה שהיה בצידן בתנאי הגט (גיטין עד,א), \u0003וראיה אחרונה\u0004 מחלוקת אחרונה שנחלק עם חכמים בענין הבאת ראיה לבית דין (סנהדרין לא,א).","ומעתה באים לדון כיצד נעשה אדם ערב, וכיצד הוא נעשה קבלן. \u0003אמר רב הונא:\u0004 אם אמר: \u0003\"הלוהו ואני ערב\",\u0004 או \u0003\"הלוהו ואני פורע\",\u0004 או \u0003\"הלוהו ואני חייב\",\u0004 או \u0003\"הלוהו ואני נותן\"\u0004 — \u0003כולן לשון ערבות הן\u0004 משום שאמר \"הלווהו\", לומר שתהא הלוואה זו למקבל, אלא שהוא מתחייב לערוב לו.","אבל אם אמר לו בלשון: \u0003\"תן לו ואני קבלן\",\u0004 או \u0003\"תן לו ואני פורע\", \"תן לו ואני חייב\",\u0004 או \u0003\"תן לו ואני נותן\"\u0004 — \u0003כולן לשון קבלנות הן,\u0004 שלשון \"תן\" משמעה — תן לו בפועל על חשבוני, אני אקבל עלי את החוב.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 השאלה ללומדים\u0005]:\u0006 אם אמר בלשון \u0003\"הלוהו ואני קבלן\",\u0004 או \u0003\"תן לו ואני ערב\", מאי\u0004 \u0005[מה]\u0006 הדין? האם הולכים אחר ההבחנה בין הלשון \"הלווהו\" לבין הלשון \"תן לו\", או שמא הולכים אחר ההבחנה בין הלשון לשון \"ערב\" לבין הלשון \"קבלן\"?","\u0003אמר ר' יצחק: לשון ערבות\u0004 — \u0003ערבות, לשון קבלנות\u0004 — \u0003קבלנות,\u0004 שאם הזכיר לשון \"ערב\" הרי הוא ערב, ואם הזכיר לשון \"קבלן\" הריהו קבלן.","\u0003רב חסדא אמר: כולן לשון קבלנות הן, בר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004הלשון \u0003\"הלוהו ואני ערב\".\u0004","ואילו \u0003רבא אמר: כולן לשון ערבות הן, בר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004הלשון \u0003\"תן לו ואני נותן\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר בר אמימר לרב אשי, הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבא:\u0004 אם אומר \u0003\"תן לו ואני נותן\"\u0004 — \u0003אין למלוה על הלוה כלום,\u0004 אלא כל התביעה היא על הערב (הקבלן) בלבד.","ודוחים: \u0003ולא היא,\u0004 אין הדבר כן, אלא \u0003לא מיפטר\u0004 \u0005[נפטר]\u0006 ה\u0003לוה מיניה\u0004 \u0005[ממנו]\u0006 מן ה\u0003מלוה עד שישא ויתן ביד,\u0004 כלומר, עד שהערב עצמו יקח את הכסף מיד המלוה ויתן ללווה בפועל, ואז תובע המלוה רק מן הערב.","מסופר: \u0003ההוא דיינא דאחתיה למלוה לנכסי דלוה מקמי דלתבעיה ללוה\u0004 \u0005[דיין אחד שהוריד את המלוה לנכסי הלווה לפני שתבע את הלווה\u0006 שיפרע הוא את חובו\u0005],\u0006 \u0003סלקיה\u0004 \u0005[סילק אותו]\u0006 את המלוה \u0003רב חנין בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ייבא\u0004 מנכסים אלה.","\u0003אמר רבא: מאן חכים למעבד כי הא מילתא\u0004 \u0005[מי חכם לעשות דבר כזה],\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003רב חנין בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ייבא!\u0004 ומה היה טעמו? — \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003נכסיה דבר איניש אינון מערבין יתיה\u0004 \u0005[נכסיו של אדם הם נעשים ערבים שלו],\u0006 ויש לדון בהם כבדין ערב, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנתנו\u0005]:\u0006 \u0003המלוה את חבירו על ידי ערב\u0004 — \u0003לא יפרע מן\u0004 \u0003הערב, וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 שפירוש הדבר: \u0003לא יתבע ערב תחלה.\u0004 וכיון שנכסיו של אדם הם רק ערבים לו — אין המלוה רשאי לגבות את חובו מנכסיו. אלא יתבע קודם מן הלווה, שמא יש בידו כסף מזומן.","ועוד בדין ערב, מסופר: \u0003ההוא ערבא דיתמי דפרעיה\u0004 \u0005[ערב אחד של יתומים שפרעו]\u0006 \u0003למלוה\u0004 את חובו \u0003מקמי דלודעינהו ליתמי\u0004 \u0005[לפני שהודיע ליתומים]\u0006 שיש חוב, ושהוא עומד לפורעו עבורם, ולאחר מכן בא לתבוע מהם את הכסף.","\u0003אמר רב פפא:\u0004 כלל הוא ש\u0003פריעת בעל חוב\u0004 היא בגדר \u0003מצוה, ויתמי\u0004 \u0005[והיתומים],\u0006 כיון שהם קטנים, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בני מיעבד\u0004 \u0005[עשיית]\u0006 \u0003מצוה נינהו\u0004 \u0005[הם],\u0006 ולכן אין הערב יכול לתבוע מהם את מה ששילם.","\u0003ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר:\u0004 אין לתבוע מן היתומים מסיבה אחרת — \u0003אימר צררי אתפסיה\u0004 \u0005[אמור\u0006 ש\u0005צרור כסף נתן לו]\u0006 אביהם בחייו, וסילק את החוב או מקצתו."],["ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ההבדל\u0006 למעשה \u0005ביניהם],\u0006 אם לשתי הדעות, בפועל אין הערב יכול לגבות מן היתומים?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 \u0003כש\u0004ה\u0003חייב,\u0004 כלומר, אביהם \u0003מודה\u0004 בשעת מותו שהוא חייב כסף זה. \u0003אי נמי\u0004 \u0003דשמתוהו\u0004 \u0005[או גם כן שנידו אותו,\u0006 את האב\u0005]\u0006 בבית דין על שלא רצה לפרוע חוב זה, \u0003ומת בשמתיה\u0004 \u0005[ב\u0006תוך \u0005נידויו],\u0006 שאז ברור שעדיין לא שילם דבר. במקרים אלה, לדעת רב פפא עדיין אין היתומים משלמים, משום שאינם חייבים במצוה. אבל לדעת רב הונא בנו של רב יהושע, כיון שיש עליהם שעבוד, וברור שלא שולם החוב — הרי הם משלמים.","\u0003שלחו מתם\u0004 \u0005[משם]\u0006 מארץ ישראל לבבל, פסק הלכה: \u0003שמתוהו ומת בשמתיה\u0004 \u0005[נידוהו ומת בנידויו],\u0006 \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003ערב שהיה שטר חוב\u0004 שקיבל מהמלוה \u0003יוצא מתחת ידו\u0004 והוא תובע את יורשי הלווה להחזיר לו מה ששילם עבורם — \u0003אינו גובה, ואם כתוב בו\u0004 בשטר החוב \u0003\"התקבלתי ממך\"\u0004 שחתם המלוה כי קיבל סכום זה מן הערב — \u0003גובה.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 — \u0003משכחת לה\u0004 \u0005[מוצא אתה]\u0006 אפשרות שיכול הערב לגבות מיתומי הלווה, כגון \u0003כשחייב מודה. אלא לרב פפא קשיא\u0004 \u0005[קשה],\u0006 שהרי לשיטתו אין הערב גובה כלל מן היתומים, שהרי אינם חייבים במצוה!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם\u0006 הדין\u0005],\u0006 במקרה מיוחד זה, כי \u0003להכי טרח וכתב ליה\u0004 \u0005[לכך\u0006 הוא \u0005טורח וכותב לו]\u0006 \u0003\"התקבלתי\",\u0004 כדי שיהא זה כשטר חוב של הערב עצמו, ובמקרה זה נכסי הלווה משועבדים לחוב, וגובים מן היתומים. אבל אין מכאן ראיה למקרה אחר.","בקשר לענין זה מסופר: \u0003ההוא ערבא\u0004 \u0005[\u0006אדם \u0005אחד\u0006 שהיה \u0005ערב]\u0006 להלוואה שהלוה \u0003גוי,\u0004 \u0003דפרעיה\u0004 \u0005[שפרעו]\u0006 \u0003לגוי מקמי דלתבעינהו ליתמי\u0004 \u0005[לפני שתבע מן היתומים],\u0006 יורשי הלווה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבימי מהגרוניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003חיישינן לצררי\u0004 \u0005[חוששים אנו\u0006 שמא נתן לו \u0005צרור כסף\u0006 ושילם לו\u0005]\u0006 — \u0003הני מילי\u0004 \u0005[דברים אלה אמורים]\u0006 כשהיה המלוה \u0003ישראל, אבל\u0004 ב\u0003גוי כיון דבתר ערבא אזיל\u0004 \u0005[שאחרי הערב\u0006 הוא \u0005הולך\u0006 לגבות\u0005]\u0006 \u0003לא חיישינן לצררי\u0004 \u0005[אין אנו חוששים לצרור כסף\u0006\u0005],\u0006 שנתן הלווה לגוי, שהוא חושש שמא בכל מקרה יחזור הגוי ויגבה מן הערב.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 לרב אשי: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 ההיפך מסתבר\u0005]:\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003לא חיישינן לצררי\u0004 \u0005[אין אנו חוששים לצרור כסף\u0006\u0005],\u0006 שהפקיד הלווה אצל המלוה — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא ב\u0003ישראל, אבל גוים כיון דדינייהו בתר ערבא אזלי\u0004 \u0005[שדינם\u0006 ש\u0005אחר הערב\u0006 הם \u0005הולכים],\u0006 \u0003אי לאו דאתפסיה צררי מעיקרא\u0004 \u0005[אם לא שהתפיסו,\u0006 שהפקיד בידו של הערב \u0005צרור מתחילה]\u0006 — \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003מקבל ליה\u0004 \u0005[עליו]\u0006 את הערבות.","שנינו במשנה, \u0003וכן היה רבן שמעון בן גמליאל אומר: הערב לאשה בכתובתה\u0004 ובעלה רוצה לגרשה, צריך הבעל לידור ממנה הנאה, כדי שלא יעשו קנוניא על הערב, ויחזיר את אשתו. מסופר: איש אחד ששמו \u0003משה בר עצרי ערבא דכתובתה דכלתיה הוה\u0004 \u0005[ערב לכתובה של כלתו היה].\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 \u0003צורבא מדרבנן הוה ודחיקא ליה מילתא\u0004 \u0005[תלמיד חכם היה ודחוק\u0006 בממון\u0005].\u0006 \u0003אמר אביי: ליכא דניזיל דנסביה\u0004 \u0005[האם אין\u0006 מי \u0005שילך ויתן]\u0006 \u0003עצה לרב הונא\u0004 זה, \u0003דנגרשה לדביתהו ותיזיל ותגבי\u0004 \u0005[שיגרש את אשתו, ו\u0006היא \u0005תלך ותגבה]\u0006 את ה\u0003כתובה מאבוה\u0004 \u0005[מאביו]\u0006 שהיה ערב לכתובה, \u0003והדר נהדרה\u0004 \u0005[ואחר כך יחזיר אותה]\u0006 רב הונא, ונמצא שיש בידו קצת כסף?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והא\u0004 \u0005[והרי]\u0006 \u0003\"ידירנה הנאה\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 ואם כן כיצד יוכל להחזיר אותה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אטו\u0004 \u0005[וכי]\u0006 \u0003כל\u0004 מי ש\u0003מגרש\u0004 אשה, \u0003בבי דינא\u0004 \u0005[בבית דין]\u0006 שהם יודעים הלכה זו \u0003מגרש?\u0004 יגרשנה שלא בפני בית דין, ולא ידירנה!","\u0003לסוף איגלאי מילתא\u0004 \u0005[התגלה הדבר]\u0006 ש\u0003כהן הוא,\u0004 וממילא לא יכול היה לגרש את אשתו ולהחזירה. \u0003אמר אביי: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]:\u0006 \u0003בתר עניא אזלא עניותא\u0004 \u0005[אחר העני הולכת העניות],\u0006 שאפילו בעצה זו אינו יכול להשתמש.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר אביי הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר אביי: איזהו \"רשע ערום\"?\u0004 — \u0003זה\u0004 \u0003המשיא עצה למכור בנכסים כ\u0004דעת \u0003רבן שמעון בן גמליאל.\u0004 שלדעתו, מי שציווה \"נכסי לך ואחריך לפלוני\", אם קדם המקבל הראשון ומכר את הנכסים — זכותו לעשות זאת, ואין לשני כלום. ואם כן, משמע שלדעת אביי, כל מי שנותן עצה לאדם לעשות דבר, שהוא אמנם חוקי אבל גורם עוול לאחרים — נקרא \"רשע ערום\", וכיצד יכול היה להשיא עצה כזאת לאותו רב הונא בר משה?","ומשיבים: במקרה זו, כיון שהבעל \u0003בנו\u0004 של הערב הוא — הרי זה \u0003שאני\u0004 \u0005[שונה],\u0006 שהוא מוחל. \u0003וצורבא מרבנן שאני\u0004 \u0005[ו\u0006כן \u0005תלמיד חכם\u0006 הרי זה \u0005שונה],\u0006 שראוי לעשות טובה לתלמיד חכם. ומקשים עוד: כיצד היתה מועילה אותה עצה?","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003ערב הוא\u0004 האב, \u0003וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 ש\u0003ערב\u0004 של \u0003כתובה לא משתעבד\u0004 באמת, אלא רק לכבוד ולמצוה בלבד הוא שנהיה ערב! ומשיבים: \u0003קבלן הוה\u0004 \u0005[היה]\u0006 ולא סתם ערב, והוא כן משתעבד לתשלום הכתובה, שהרי קיבל על עצמו במפורש את חובת התשלום.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003קבלן\u0004 של \u0003כתובה אף על גב דלית ליה נכסי\u0004 \u0005[אף על פי שאין לו נכסים]\u0006 \u0003לבעל\u0004 בכל זאת \u0003משתעבד\u0004 — \u0003שפיר\u0004 \u0005[יפה].\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003אי אית ליה\u0004 \u0005[אם יש לו]\u0006 נכסים לבעל \u0003משתעבד\u0004 הקבלן, \u0003אי לית ליה\u0004 \u0005[אם אין לו]\u0006 — \u0003לא משתעבד,\u0004 שבוודאי לא התכוון לשלם את הכתובה, אם כן, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 כיצד היתה מועילה אותה עצה?","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003מיהוי הוה ליה\u0004 \u0005[היו לו]\u0006 נכסים, לרב הונא זה בזמן הנישואין, כשקיבל האב על עצמו את הערבות, \u0003ואישתדוף\u0004 \u0005[ו\u0006אחר כך \u0005נשדפו].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אבא לגבי בריה שעבודי משעבד נפשיה\u0004 \u0005[האב לגבי בנו\u0006 בוודאי \u0005משעבד\u0006 את \u0005עצמו\u0006\u0005]\u0006 גם כאשר אין לבן נכסים. ומהי אותה מחלוקת לגבי קבלן של כתובה?","\u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003ערב\u0004 של \u0003כתובה\u0004 — \u0003דברי הכל לא משתעבד,\u0004 שמכיון שלא היתה כאן הלוואה במתן כסף, וגם לא היה הערב אלא לכבוד ולמצוה בלבד. ערב \u0003קבלן\u0004 של \u0003בעל חוב\u0004 (של הלוואה) — \u0003דברי הכל משתעבד.\u0004 לגבי \u0003קבלן\u0004 של \u0003כתובה, ו\u0004לגבי \u0003ערב\u0004 סתם ל\u0003בעל חוב\u0004 — בזה \u0003פליגי\u0004 \u0005[חלוקים\u0006 חכמים\u0005],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה סבור]:\u0006 \u0003אי אית ליה נכסי\u0004 \u0005[אם יש לו נכסים]\u0006 \u0003ללוה\u0004 — \u0003משתעבד\u0004 הערב, שהוא מקבל על עצמו ערבות מתוך הנחה שלא יצטרך לפרוע את החוב, ואין זה אלא לשם בטחון. \u0003אי לית ליה\u0004 \u0005[אם אין לו]\u0006 נכסים ללווה — \u0003לא משתעבד. ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003בין אית ליה\u0004 \u0005[\u0006ש\u0005יש לו]\u0006 \u0003ובין לית ליה\u0004 \u0005[\u0006ש\u0005אין לו]\u0006 — \u0003משתעבד\u0004 הערב.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]\u0006 שכל \u0003ערב, בין אית ליה\u0004 \u0005[\u0006ש\u0005יש לו]\u0006 נכסים ללווה \u0003ובין לית ליה\u0004 \u0005[\u0006ש\u0005אין לו]\u0006 — \u0003משתעבד\u0004 הערב, \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003מערב\u0004 של \u0003כתובה, דאף על גב דאית ליה\u0004 \u0005[שאף על פי שיש לו]\u0006 נכסים \u0003לבעל\u0004 — בכל זאת \u0003לא משתעבד. מאי טעמא\u0004 \u0005[מה טעם ה\u0006דבר\u0005]?\u0006 — \u0003מצוה הוא דעבד\u0004 \u0005[שעשה]\u0006 כדי שיינשאו בני הזוג, \u0003ולאו מידי חסרה\u0004 \u0005[ו\u0006גם האשה \u0005אינה חסרה דבר]\u0006 בזמן הנישואין, שהוא מקבל על עצמו לפורעו.","\u0003אמר רב הונא: שכיב מרע שהקדיש כל נכסיו, ואמר \"מנה לפלוני בידי\"\u0004 שאני חייב לו — הרי זה \u0003נאמן\u0004 בדבריו, ומדוע? — \u0003חזקה אין אדם עושה קנוניא\u0004 (רמאות) \u0003על\u0004 ה\u0003הקדש,\u0004 ואם אמר שהוא חייב לאדם אחר — בוודאי אמר אמת.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן: וכי\u0004 אומרים ש\u0003אדם עושה קנוניא על בניו?\u0004 ובכל זאת מצאנו ש\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]:\u0006 \u0003שכיב מרע שאמר \"מנה לפלוני בידי\"\u0004 שאני חייב לו, הרי רק אם \u0003אמר \"תנו\u0004 לו מנה זה \u0003\"\u0004— \u0003נותנין,\u0004 אבל אם \u0003לא אמר \"תנו\"\u0004 — \u0003אין נותנין; אלמא\u0004 \u0005[מכאן]\u0006 שאנו מניחים כי \u0003אדם עשוי\u0004 לומר שהוא חייב כסף לאחרים רק כדי \u0003שלא להשביע את בניו,\u0004 כלומר, כדי שבניו לא ייחשבו עשירים בעיניהם של הבריות."],["\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לגבי המקדיש נכסיו, יש לומר: \u0003אדם עשוי שלא להשביע את עצמו,\u0004 שלא יחשבו אותו בחייו לעשיר, ומדוע סומכים על דבריו ונותנים את המנה לאותו פלוני?!","ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב הונא התם\u0004 \u0005[שם]\u0006 שמאמינים למקדיש, הרי זה במקרה \u0003דנקיט שטרא\u0004 \u0005[שמחזיק\u0006 אותו פלוני \u0005שטר\u0006 חוב\u0005],\u0006 וניכר שבאמת היה חייב לו.","ושואלים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003רב ושמואל\u0004 דיברו במקרה ש\u0003לא נקיט שטרא\u0004 \u0005[מחזיק שטר],\u0006 ויש לתמוה: לשיטתם, אם \u0003אמר\u0004 לבניו \u0003\"תנו\"\u0004 — \u0003נותנין?\u0004 הלא אם אין בידי המלוה שטר, אם כן \u0003מלוה על פה הוה\u0004 \u0005[הוא],\u0006 \u0003ו\u0004הרי \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מלוה על פה\u0004 — \u0003אינו גובה לא מן היורשין ולא מן הלקוחות!\u0004","\u0003אלא אמר רב נחמן: אידי ואידי דנקיט שטרא\u0004 \u0005[זה וזה,\u0006 בכל מקרה מדובר \u0005שמחזיק שטר],\u0006 \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שנאמן בכל מקרה — הרי זה כשהיה השטר של בעל החוב שטר \u0003מקויים, הא\u0004 \u0005[זה]\u0006 במקרה שדיברו עליו רב ושמואל — \u0003לא\u0004 היה השטר \u0003מקויים,\u0004 ולכן אם \u0003אמר \"תנו\"\u0004 — \u0003קיימיה לשטריה\u0004 \u0005[קיים את שטרו],\u0006 שהרי הודה שהשטר הוא אמיתי, אבל אם \u0003לא אמר \"תנו\"\u0004 — \u0003לא קיימיה לשטריה\u0004 \u0005[קיים את שטרו],\u0006 ויש איפוא לחשוש שהתכוון רק שלא להשביע את בניו.","ועוד בעניינים אלו, \u0003אמר רבה: שכיב מרע שאמר \"מנה לפלוני בידי\", ואמרו יתומין \"פרענו\u0004 חוב זה \u0003\"\u0004— \u0003נאמנין.\u0004 אם אמר בלשון ציווי \u0003\"תנו מנה לפלוני\", ואמרו יתומין \"פרענו\"\u0004 — \u0003אין נאמנין.\u0004","ותוהים: \u0003כלפי לייא\u0004 \u0005[לאן אתה הולך]?\u0006 כלומר, דברים תמוהים והפוכים הם, שהרי \u0003איפכא מסתברא\u0004 \u0005[ההיפך מסתבר]!\u0006 אם \u0003אמר \"תנו מנה\"\u0004 — \u0003כיון דפסקה אבוהון למילתא\u0004 \u0005[שפסק אביהם את הדבר]\u0006 ואמר \"תנו\", \u0003איכא למימר דפרעיה\u0004 \u0005[יש לומר שפרע\u0006 הבן \u0005אותו],\u0006 את החוב. אבל אם אמר רק \u0003\"מנה לפלוני בידי\"\u0004 — \u0003כיון\u0004 ש\u0003לא פסק אבוהון למילתא\u0004 \u0005[אביהם את הדבר]\u0006 ולא אמר \"תנו\", \u0003איכא למימר דלא פרעיה\u0004 \u0005[יש לומר שלא פרע\u0006 הבן \u0005אותו]!\u0006","\u0003אלא אי איתמר הכי איתמר\u0004 \u0005[אם נאמר\u0006 הדבר על ידי רבה, \u0005כך נאמר],\u0006 ובאופן אחר: \u0003שכיב מרע שאמר \"מנה לפלוני בידי\", ואמרו\u0004 ה\u0003יתומין: חזר ואמר לנו אבא \"פרעתי\u0004 חוב זה \u0003\"\u0004— \u0003נאמנין, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003אדכורי מידכר\u0004 \u0005[נזכר\u0006 הוא\u0005]\u0006 לאחר מכן שפרע. אבל אם אמר \u0003\"תנו מנה לפלוני\", ואמרו\u0004 ה\u0003יתומין: \"חזר ואמר אבא פרעתי\"\u0004 — \u0003אין נאמנין,\u0004 ומדוע? — ש\u0003אם איתא דפרעיה\u0004 \u0005[יש\u0006 מקום לומר \u0005שפרע לו],\u0006 \u0003לא הוה אמר\u0004 \u0005[היה אומר]\u0006 בהחלטיות \u0003\"תנו\".\u0004","ועוד בענייני שכיב מרע שהודה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: שכיב מרע שהודה\u0004 בפני עדים שהוא חייב לפלוני כסף, \u0003מהו\u0004 דינו? האם גם שכיב מרע, כמו בריא שמודה בפני עדים, \u0003צריך לומר\u0004 לאנשים העומדים שם \u0003\"אתם עדי\",\u0004 כדי שתהא הודעה זו מחייבת, \u0003או אין צריך לומר\u0004 להם \u0003\"אתם עדי\"?\u0004 וכיוצא בזה, האם \u0003צריך שיאמר\u0004 לעדים \u0003\"כתובו\u0004 הודאה זו \u0003\",\u0004 כדי שיהיו רשאים לכתוב, \u0003או אין צריך לומר \"כתובו\"?\u0004 ודבר זה תלוי בשאלה: האם \u0003אדם משטה בשעת מיתה.\u0004 כלומר, האם יש לחשוש שלא התכוון ברצינות למה שאמר, כפי שאנו חוששים לכך באדם בריא, \u0003או אין אדם משטה בשעת מיתה?\u0004","\u0003בתר דבעיא הדר פשטה\u0004 \u0005[אחר ששאל\u0006 רבא את השאלה \u0005חזר\u0006 ו\u0005פתר אותה]:\u0006 \u0003אין אדם משטה בשעת מיתה\u0004 ומתכוון למה שאומר, ולפיכך הודאתו מחייבת גם אם לא אמר \"אתם עדי\", \u0003ודברי שכיב מרע ככתובין וכמסורין דמו\u0004 \u0005[נחשבים],\u0006 ולכן יש להם רשות לכתוב שטר גם אם לא אמר להם לכתוב.","\u0003המלוה את חבירו בשטר\u0004 — הרי המלוה \u0003גובה\u0004 על סמך השטר \u0003מנכסים משועבדים\u0004 (שהיו ברשותו בזמן ההלוואה, ומכרם). אבל אם מלוה את חבירו \u0003על ידי עדים,\u0004 שלא בשטר — \u0003גובין\u0004 את חובו רק \u0003מנכסים בני חורין,\u0004 ולא מנכסים שנמכרו לאחרים."],["\u0003הוציא\u0004 המלוה \u0003עליו\u0004 על הלווה, מסמך כתוב ב\u0003כתב ידו\u0004 של הלווה \u0003שהוא חייב לו\u0004 — \u0003גובה\u0004 המלוה רק \u0003מנכסים בני חורין.\u0004","אם היה \u0003ערב היוצא לאחר חיתום שטרות,\u0004 שאחר חתימת העדים בשטר כתוב שפלוני ערב לפרעון חוב זה — \u0003גובה\u0004 בעל החוב מן הערב רק \u0003מנכסים בני חורין.\u0004","\u0003מעשה ובא\u0004 שטר חוב כזה \u0003לפני ר' ישמעאל, ואמר: גובה\u0004 המלוה מן הערב רק \u0003מנכסים בני חורין. אמר לו\u0004 החכם שמעון \u0003בן ננס: אינו גובה\u0004 כלל \u0003לא מנכסים משועבדים ולא מנכסים בני חורין.\u0004","\u0003אמר לו: למה? אמר לו:\u0004 דוגמה לדבר, \u0003הרי\u0004 אדם \u0003החונק\u0004 \u0003את אחד בשוק\u0004 ותובע ממנו את חובו, \u0003ומצאו חבירו ואמר לו\u0004 לתוקף \u0003\"הנח לו ואני אתן לך\"\u0004 — והניחו, אם יבוא התוקף לתבוע את החוב מן החבר שהבטיח לתת — \u0003פטור\u0004 אותו חבר מלתת, ומדוע? — לפי \u0003שלא על אמונתו\u0004 בו \u0003הלוהו,\u0004 כלומר, שלא משום שסמך על זה הילוה לחבירו מתחילה, ולא בכך היה החוב תלוי, ולכן אינו יכול לתבוע ממנו לאחר מכן. וכך גם ערב החותם לאחר שכבר נחתם שטר ההלוואה — כבר הילוה המלוה ללווה גם בלא הערב. \u0003אלא איזה הוא ערב שהוא חייב\u0004 לשלם? — אם אמר הערב \u0003\"הלוהו ואני נותן לך\"\u0004 — אז \u0003חייב, שכן על\u0004 סמך \u0003אמונתו\u0004 של הערב \u0003הלוהו.\u0004","\u0003ואמר ר' ישמעאל: הרוצה שיחכים\u0004 — \u0003יעסוק בדיני ממונות, שאין לך מקצוע בתורה יותר מהן\u0004 בריבוי הלכות וסברות, \u0003והן כמעיין הנובע, והרוצה שיעסוק בדיני ממונות\u0004 — \u0003ישמש את שמעון בן ננס\u0004 שהוא חריף ביותר.","ודנים בסוגיה עקרונית הקשורה למשנתנו. \u0003אמר עולא: דבר תורה, אחד מלוה בשטר ואחד\u0004 \u0003מלוה על פה\u0004 — \u0003גובה מנכסים משועבדים, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003שעבודא\u0004 \u0005[\u0006דין \u0005השעבוד]\u0006 של נכסי הלווה למלווה, שגם אם ימכרם או יתנם יכול המלוה לגבות מהם — הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ואלא מה טעם אמרו\u0004 חכמים ש\u0003מלוה על פה\u0004 \u0003אינו גובה אלא מנכסין בני חורין?\u0004 — \u0003משום פסידא\u0004 \u0005[ההפסד]\u0006 של ה\u0003לקוחות,\u0004 שמא לא ידעו שלווה, ויקנו מן הלווה נכסים, ויפסידו כשייקחם המלוה בחובו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם לכך חוששים, \u0003מלוה בשטר נמי\u0004 \u0005[גם כן]\u0006 לא יגבה ממשועבדים, משום הפסד הלקוחות! ומשיבים: \u0003התם אינהו נינהו דאפסידו אנפשייהו\u0004 \u0005[שם הם הם שהפסידו לעצמם],\u0006 שכן מילוה בשטר הוא דבר מפורסם, ויכלו לברר אם לוה כסף.","\u0003ו\u0004אילו \u0003רבה אמר: דבר תורה, אחד מלוה בשטר ואחד מלוה על פה\u0004 — \u0003אינו גובה אלא מנכסים בני חורין. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — שהוא סבור \u0003שעבודא לאו דאורייתא\u0004 \u0005[שעבוד לא מן התורה\u0006 הוא\u0005],\u0006 ומדין תורה אין ההלוואה אלא התחייבות של הלווה עצמו, ואינה חלה על נכסיו. \u0003ומה טעם אמרו\u0004 חכמים ש\u0003מלוה בשטר גובה מנכסים משועבדים? כדי שלא תנעול דלת בפני לוין,\u0004 שאם לא יוכלו מלוים להבטיח את פרעון חובם — לא ירצו להלוות.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מלוה על פה נמי\u0004 \u0005[גם כן]\u0006 יגבה מאותו טעם מנכסים משועבדים! ומשיבים: \u0003התם לית ליה קלא\u0004 \u0005[שם אין לו קול\u0006 לדבר\u0005],\u0006 שאין הדבר מתפרסם, ויש לחשוש להפסד הלקוחות.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבה הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבה,\u0004 בביאור הלכה שנשלחה מארץ ישראל, שהבכור יש לו חלק כפול במילוה שהיו חייבים לאביו: אם \u0003גבו קרקע\u0004 כתשלום מילוה זה — \u0003יש לו,\u0004 לבכור, פי שניים. אם \u0003גבו מעות\u0004 — \u0003אין לו.\u0004 וטעמו של דבר — משום שמתחילת ההלוואה כבר נשתעבדו נכסי הלווה לתשלום ההלוואה, והריהם ברשות אביו. משמע שמדין תורה חל שעבוד חוב על קרקע!","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 בתירוץ הדברים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את שמות בעלי השיטות הללו, וייחס את מה שאמר \u0003רבה לעולא ו\u0004את מה שאמר \u0003עולא לרבה,\u0004 שלדעת רבה שעבוד נכסים היא מן התורה, ולדעת עולא הוא אינו מן התורה, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר עולא:\u0004 \u0003דבר תורה,\u0004 מן התורה, \u0003בעל חוב דיניה\u0004 \u0005[דינו]\u0006 שמשלם \u0003ב\u0004קרקע \u0003זבורית\u0004 (גרועה)!","\u0003אלא\u0004 יש להבין כי \u0003רבה טעמא דבני מערבא קאמר\u0004 \u0005[\u0006את \u0005הטעם,\u0006 השיטה \u0005של בני ארץ ישראל אמר\u0006 והסביר\u0005],\u0006 \u0003וליה לא סבירא ליה\u0004 \u0005[והוא עצמו אינו סבור]\u0006 שהשעבוד הוא מן התורה. ובאותו נושא נחלקו אמוראים ראשונים.","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מלוה על פה\u0004 — \u0003אינו גובה לא מן היורשין ולא מן הלקוחות, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003שעבודא לאו דאורייתא\u0004 \u0005[השעבוד\u0006 של נכסי הלווה \u0005לא מן התורה\u0006 הוא\u0005],\u0006 ורק במילוה בשטר תיקנו חכמים שעבוד.","ואילו \u0003ר' יוחנן ור' שמעון בן לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מלוה על פה\u0004 — \u0003גובה בין מן היורשין\u0004 של הלווה לאחר מותו, \u0003ובין מן הלקוחות, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003שעבודא דאורייתא\u0004 \u0005[שעבוד\u0006 הנכסים \u0005מן התורה\u0006 הוא\u0005],\u0006 בכל דרך שנעשתה ההלוואה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב ושמואל ממה ששנינו: \u0003החופר בור ברשות הרבים ונפל עליו\u0004 על החופר \u0003שור והרגו\u0004 — \u0003פטור\u0004 בעל השור, שהרי לא הוא אשם בכך. \u0003ולא עוד, אלא שאם מת השור\u0004 בנפילתו זו — \u0003יורשי בעל הבור חייבים לשלם דמי שור לבעליו,\u0004 כדין החופר בור ברשות הרבים. והרי התחייבותו של בעל הבור לשלם דמי השור אינה כתובה בשטר, אלא היא כמילוה על פה, ובכל זאת יורשיו צריכים לשלם. משמע שמילוה על פה גובה מן היורשים!","\u0003אמר ר' אלעא אמר רב:\u0004 שם מדובר \u0003בשעמד\u0004 בעל הבור \u0003בדין\u0004 ונתחייב. ופסק של בית הדין (גם אם לא נכתב) יש לו תוקף כשטר חוב, ולכן חייבים היורשים לשלם.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"הרגו\u0004 השור \u0003\"\u0004\u0003קתני\u0004 \u0005[שנינו],\u0006 וכיצד יכול חופר הבור לעמוד בדין? \u0003אמר רב אדא בר אהבה:\u0004 אין מדובר במקרה שנהרג אותו איש במקום, אלא \u0003שעשאו\u0004 השור \u0003טרפה,\u0004 שגרם לו נזקים חמורים שמת מחמתם לאחר זמן, ולפני מותו דנו אותו.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב נחמן, תני\u0004 \u0005[שנה]\u0006 ה\u0003תנא,\u0004 שונה המשניות: \u0003מת וקברו\u0004 שקבר אותו השור בתוך הבור בנפילתו, ואם כן לא עמד בדין! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003דיתבי דייני אפומא דבירא\u0004 \u0005[שישבו הדיינים על פי הבור]\u0006 \u0003וחייבוהו\u0004 לפני שמת."],["\u0003אמר רב פפא, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003מלוה על פה\u0004 — \u0003גובה מן היורשין ואינו גובה מן הלקוחות. גובה מן היורשין\u0004 — \u0003כדי שלא תנעול דלת בפני לוין, ואינו גובה מן הלקוחות\u0004 — \u0003דלית ליה קלא\u0004 \u0005[שאין לו\u0006 למילוה על פה \u0005קול],\u0006 ויימצאו הלקוחות מפסידים את הקרקע שקנו.","שנינו במשנה שאם \u0003הוציא עליו כתב ידו שהוא חייב לו\u0004 — \u0003גובה מנכסים בני חורין וכו'. בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבה בר נתן מר' יוחנן:\u0004 אם \u0003הוחזק כתב ידו\u0004 של אותו אדם \u0003בבית דין,\u0004 שאישרו בית דין שזו חתימתו, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם לאחר שהוחזק כתב היד בבית הדין נעשה דינו כהלוואה בשטר, ויכול לגבות גם מנכסים משועבדים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף על פי שהוחזק כתב ידו בבית דין\u0004 — \u0003אינו גובה אלא מנכסים בני חורין.\u0004","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רמי בר חמא\u0004 ממה ששנינו במשנה: \u0003שלשה גיטין פסולין\u0004 לכתחילה, ואין האשה המתגרשת בהם מותרת להינשא על סמך גיטין אלה, \u0003ו\u0004אולם \u0003אם נישאת\u0004 האשה על סמך גיטין אלה — \u0003הולד\u0004 שנולד מנישואיה אלה \u0003כשר\u0004 בדיעבד. \u0003ואלו הן:\u0004 אם \u0003כתב\u0004 את הגט \u0003בכתב ידו\u0004 בלבד \u0003ואין עליו עדים,\u0004 או \u0003יש עליו עדים ואין בו זמן\u0004 (תאריך), או \u0003יש בו זמן ואין בו אלא עד אחד\u0004 — \u0003הרי אלו שלשה גיטין פסולין, ואם נישאת\u0004 — \u0003הולד כשר.\u0004","\u0003ר' אלעזר אומר: אף על פי שאין עליו עדים אלא שנתנו לה בפני עדים\u0004 — \u0003כשר, ו\u0004אם היה שטר חוב שנעשה באופן זה — \u0003גובה\u0004 בו גם \u0003מנכסים משועבדים.\u0004 משמע שעל ידי מסירת השטר בעדים נעשה כתב יד כשטר שיש בו עדים, וגובה בו ממשועבדים. ומדוע לא נאמר כן אף בכתב ידו שאושר בבית הדין!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003משעת כתיבה\u0004 של השטר \u0003הוא דשעבד נפשיה\u0004 \u0005[ששיעבד עצמו],\u0006 שהרי מתחילתו נכתב כדי להימסר בעדים, ולשם שעבוד נכסים. מה שאין כן בכתב ידו שקיימוהו בית דין לאחר זמן, שבזמן כתיבתו לא נכתב כלל כדי לשעבד נכסיו.","שנינו במשנה שב\u0003ערב היוצא,\u0004 ערבות הכתובה בשטר \u0003לאחר חיתום שטרות\u0004 (חתימות העדים) — גובה המלוה מן הערב רק מנכסים בני חורין. \u0003אמר רב:\u0004 אם היה הערב \u0003קודם חיתום שטרות\u0004 — \u0003גובה מנכסים משועבדים, לאחר חיתום שטרות\u0004 — \u0003גובה מנכסים בני חורין\u0004 בלבד. וכדברי המשנה.","\u0003זמנין\u0004 \u0005[פעמים]\u0006 \u0003אמר\u0004 \u0003רב: אפילו\u0004 היתה חתימת הערב \u0003קודם חיתום שטרות\u0004 — \u0003אינו גובה אלא מנכסים בני חורין.\u0004","ושואלים: אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רב\u0004 על דברי \u0003רב!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאינו גובה מנכסים משועבדים מדובר ש\u0003כתב ביה\u0004 \u0005[שכתוב בו]\u0006 \u0003\"פלוני ערב\",\u0004 שמשמע מניסוח זה שהערבות היא ענין לעצמו, ולא חתמו העדים על כך, אלא רק על גופו של שטר ההלוואה. \u0003הא\u0004 \u0005[זה]\u0006 שגובה ממשועבדים, מדובר ש\u0003כתב ביה\u0004 \u0005[שכתוב בו]\u0006 \u0003\"ופלוני ערב\",\u0004 ב־ ו' החיבור, הרי זה בא לומר שהערבות קשורה לגוף השטר, והעדים חתמו גם על הערבות, ולכן גובה הערב גם מנכסים משועבדים.","\u0003ור' יוחנן אמר: אחד זה ואחד זה\u0004 — \u0003אינו גובה אלא מנכסים בני חורין, ואף על גב דכתב ביה\u0004 \u0005[ואף על פי שכתוב בו]\u0006 \u0003\"ופלוני ערב\",\u0004 ב־ו' החיבור","\u0003. מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 על דברי ר' יוחנן, ממה ששנינו בברייתא: \u0003עדים החתומין על שאילת שלום בגט\u0004 — \u0003פסול,\u0004 כלומר, מתחת לנוסח הגט נכתבה גם דרישת שלום למישהו, וחתמו העדים למטה — פסול גט זה, \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא על שאילת שלום\u0004 בלבד \u0003חתמו.\u0004","\u0003ואמר ר' אבהו, לדידי מיפרשא ליה מיניה\u0004 \u0005[לי עצמי מתפרש ממנו]\u0006 מ\u0003ר' יוחנן:\u0004 שאם היה כתוב שם \u0003\"שאילו\"\u0004 \u0005[שאלו\u0006 בשלום פלוני\u0005]\u0006 — הרי זה גט \u0003פסול\u0004 משום ששאלת השלום היא ענין לעצמו, ואינה מתחברת על הגט שקדם לה. אבל אם היה כתוב \u0003\"ושאילו\"\u0004 \u0005[ושאלו\u0006 בשלום פלוני\u0005],\u0006 ב ־ו' החיבור, שמשמע ששני הדברים מחוברים — הרי זה גט \u0003כשר.\u0004 משמע שאם מוסיף משפט המתחיל ב־ו' החיבור אנו אומרים שחתימת העדים היא על הכל, וכאן אמר ר' יוחנן שאין הבדל!","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין ערבות, יש לתקן את נוסח הדברים ולומר כי לדעת ר' יוחנן דווקא כאשר \u0003כתב \"פלוני ערב\"\u0004 אינו גובה מנכסים משועבדים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003היינו\u0004 \u0005[הרי זה]\u0006 ממש כדברי \u0003רב,\u0004 ואינו חולק עליו! ומשיבים: אכן, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003וכן אמר ר' יוחנן\u0004 כדברי רב.","שנינו במשנה: \u0003מעשה ובא לפני ר' ישמעאל\u0004 בערב שיצא לאחר חיתום שטרות, ופסק שגובה מנכסים בני חורין. וחלק עליו בן ננס ואמר שאינו גובה ממנו כלל. והוכיח זאת מן המקרה של החונק את חבירו בשוק לגבות חובו, שהמצילו מיד החונק כשאומר לו \"הנח לו ואני אתן לך\" — אינו מתחייב בכך, לפי שלא עליו סמך כשהילוה לו, ושיבח ר' ישמעאל מאד את חכמתו של בן ננס. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: אף על פי שקילס\u0004 (שיבח) \u0003ר' ישמעאל את בן ננס,\u0004 בכל זאת \u0003הלכה כמותו\u0004 כר' ישמעאל בערב לאחר חיתום שטרות, שגובה מנכסים בני חורין.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003בחנוק\u0004 עצמו \u0003מה לי אמר ר' ישמעאל?\u0004 האם ר' ישמעאל מודה בזה לבן ננס? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ש\u0003אמר ר' יעקב אמר ר' יוחנן: חלוק היה ר' ישמעאל אף בחנוק.\u0004","ושואלים: \u0003הלכה כמותו\u0004 כר' ישמעאל, בחנוק, \u0003או אין הלכה כמותו?\u0004 ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: חלוק היה ר' ישמעאל אף בחנוק, והלכה כמותו אף בחנוק.\u0004","ובענין זה \u0003אמר רב יהודה אמר שמואל: חנוק,\u0004 שתפסו בעל חובו בשוק, ובא חבירו וערב עבורו, \u0003וקנו מידו,\u0004 כלומר, עשו קנין (סודר) על כך, שאכן ישלם את החוב — הרי הוא \u0003משתעבד\u0004 לשלם את החוב. ומעירים על כך: \u0003מכלל\u0004 דברי שמואל אתה למד, ש\u0003ערב בעלמא\u0004 \u0005[סתם]\u0006 שחותם על שטר הלוואה רגיל, \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003קנין\u0004 על מנת שישתעבד, אלא די באמירה בלבד בלבד. \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטה זו על דברי \u0003רב נחמן,\u0004 ש\u0003אמר רב נחמן:\u0004"],["\u0003ערב\u0004 של \u0003בית דין,\u0004 כלומר, שנעשה ערב לחוב בפני בית דין \u0003הוא דלא בעי\u0004 \u0005[שאינו צריך]\u0006 \u0003קנין, הא בעלמא בעי\u0004 \u0005[אבל בסתם\u0006 ערב \u0005צריך]\u0006 \u0003קנין.\u0004","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003ערב,\u0004 אם היה שם \u0003בשעת מתן מעות\u0004 מן המלוה ללווה — \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003קנין,\u0004 שעל סמך ערבותו הקנה לו, אם היה זה \u0003אחר מתן מעות\u0004 — \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003קנין. ערב\u0004 של \u0003בית דין לא בעי\u0004 \u0005[צריך]\u0006 \u0003קנין\u0004 כלל בכל מקרה, \u0003דבההיא\u0004 \u0005[שבאותה]\u0006 \u0003הנאה דמהימן ליה\u0004 \u0005[שמאמינים לו]\u0006 בבית דין — \u0003גמר\u0004 \u0005[גומר\u0006 בדעתו\u0005]\u0006 \u0003ומשעבד ליה\u0004 \u0005[לו]\u0006 את רכושו כערב.",""]]};
